  var entityMap = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': '&quot;',
  "'": '&#39;',
  "/": '&#x2F;'
};

function escapeHtml(string) {
  escapedHtml = string.split('<s>').join(' ');

  escapedHtml = String(escapedHtml).replace(/[&<>"'\/]/g, function (s) {
    return entityMap[s];
  });
  
  
  escapedHtml = escapedHtml.replace('scr&lt;wbr&gt;ipt', 'scr<wbr>ipt');

  var flag = false;
  var cnt = 0;
  var max = 30;
  var escapedString = '';
  for(x=0;x<escapedHtml.length;x++){
    if(escapedHtml.substring(x,x+11) == "joeboxbreak"){
  		escapedString += "<br/>";
  		x += 10;
  	}else{
      if(flag && escapedHtml.charAt(x) == ";"){
        flag = false;
      }else if(escapedHtml.charAt(x) == "&" || escapedHtml.charAt(x) == "<"){
        flag = true;
      }
      if(!flag){
        cnt++;
      }
      if(!flag && ((cnt % max) == 0)){
        escapedString += escapedHtml.charAt(x) + '<wbr/>';
      }else{
        escapedString += escapedHtml.charAt(x);
      }
    }

  }
  return escapedString;
}

function escapeHtmlWithoutWbr(string) {
  escapedHtml = string.split('<s>').join(' ');

  escapedHtml = String(escapedHtml).replace(/[&<>"'\/]/g, function (s) {
    return entityMap[s];
  });
  
  
  escapedHtml = escapedHtml.replace('scr&lt;wbr&gt;ipt', 'scr<wbr>ipt');
  var flag = false;
  var cnt = 0;
  var max = 30;
  var escapedString = '';
  for(x=0;x<escapedHtml.length;x++){
    if(escapedHtml.substring(x,x+11) == "joeboxbreak"){
      escapedString += "<br/>";
      x += 10;
    }else{
      if(flag && escapedHtml.charAt(x) == ";"){
        flag = false;
      }else if(escapedHtml.charAt(x) == "&" || escapedHtml.charAt(x) == "<"){
        flag = true;
      }
      if(!flag){
        cnt++;
      }
      escapedString += escapedHtml.charAt(x);
    }
  }
  return escapedString;
}

function bolderizeUpercaseWordsThatEndWithDoublePoints(string) {
  var words = string.split(' ');
  var answer = '';
  var isFirst = true;
  for (var i = 0; i < words.length; i += 1) {
        var firsLetter = words[i][0];
        var lastLetter = words[i][words[i].length-1];
        if(words[i+1]){
          var lastLetterNextWord = words[i+1][words[i+1].length-1];
        }else{
          var lastLetterNextWord = '';
        }
        if(firsLetter && lastLetter){
          if(lastLetter == ':'){
            var checkWord = words[i].slice(0, -1);
          }else{
            var checkWord = words[i];
          }
          if(checkWord == 'Path' || checkWord == 'Offset' || checkWord == 'Flags' || checkWord == 'Mode' || checkWord == 'Type' || checkWord == 'Length' || checkWord == 'Whence' || checkWord == 'Value' || checkWord == 'MIB' || checkWord == 'Baseaddress' || checkWord == 'Size' || checkWord == 'Protection' || checkWord == 'Target' || checkWord == 'Access' || checkWord == 'Options' || checkWord == 'Attributes' || checkWord == 'Content' || checkWord == 'Info' || checkWord == 'Data' || checkWord == 'Timeout' || checkWord == 'Index' || checkWord == 'Name' || checkWord == 'Port' || checkWord == 'IP' || checkWord == 'TID' || checkWord == 'PID' || checkWord == 'Cmdline' || checkWord == 'Createflags' || checkWord == 'Handle' || checkWord == 'Time' || checkWord == 'HWND' || checkWord == 'CMD' || checkWord == 'Desktop' || checkWord == 'Parent' || checkWord == 'Children' || checkWord == 'HWNDs' || checkWord == 'Exit' || checkWord == 'Base'|| checkWord == 'Input' || checkWord == 'Output Buffer' || checkWord == 'WParam' || checkWord == 'LParam' || checkWord == 'Message' || checkWord == 'Imagepath' || checkWord == 'Injected' || checkWord == 'Base' || checkWord == 'Message' || checkWord == 'Info' || checkWord == 'Overwritten' || checkWord == 'Information' || checkWord == 'Start' || checkWord == 'Username' || checkWord == 'User' || checkWord == 'Configuration' || checkWord == 'Machine' || checkWord == 'Host' || checkWord == 'Module' || checkWord == 'TID' || checkWord == 'Hook' || checkWord == 'Found' || checkWord == 'On' || checkWord == 'Disposition' || checkWord == 'Filemask' || checkWord == 'Keyname' || checkWord == 'Mapped' || checkWord == 'Watch' || checkWord == 'Filter' || checkWord == 'Last' || checkWord == 'Change' || checkWord == 'File' || checkWord == 'Old' || checkWord == 'EIP' || checkWord == 'Write' || checkWord == 'Class' || checkWord == 'Allocation' || checkWord == 'Output'){
            if ((firsLetter == firsLetter.toUpperCase() && !(firsLetter >= '0' && firsLetter <= '9') &&(firsLetter >='A' && firsLetter <= 'Z')) && lastLetter == ':') {
              if(isFirst){
                answer += '<span class="chrono-title-word">'+ words[i] + '</span> ';
                isFirst = false;
              }else{
                answer += '<br><span class="chrono-title-word">'+ words[i] + '</span> ';
              }
            }else if((firsLetter == firsLetter.toUpperCase() && !(firsLetter >= '0' && firsLetter <= '9') &&(firsLetter >='A' && firsLetter <= 'Z')) && lastLetterNextWord == ':'){
              if(isFirst){
                answer += '<span class="chrono-title-word">'+ words[i] + ' ' + words[i+1] + '</span> ';
                isFirst = false;
              }else{
                answer += '<br><span class="chrono-title-word">'+ words[i] + ' ' + words[i+1] + '</span> ';
              }
              i++;
            }
          }else{
            answer += words[i] + ' ';
          }
      }
  }
  return answer;
}

