// decodeURI throw an error if the URL is malformed. This function
// catches the error and keeps the original text instead. -->
function decodeURIIgnoreErrors(text) {
  var decodedText = "";

  var i = 0;
  while (i < text.length) {
    var j = text.length;
    while (true) {
      if (j - i <= 1) {
        // copy single characters verbatim
        decodedText += text.substring(i, j);
      } else {
        // try decoding substring from i to j
        try {
          decodedText += decodeURI(text.substring(i, j));
        } catch (err) {
          // decrement substring length and try again
          j--;
          continue;
        }
      }
      i = j;
      break;
    }
  }

  return decodedText;
}

$(document).ready(function() {
  $('.decodeUri').each(function(){
    $(this).text(decodeURIIgnoreErrors($(this).text()));
  });
});



function spiderChart(id, data, options) {

	var settings = {
		w: 600,
		h: 600,
		margin: {top: 20, right: 20, bottom: 20, left: 20},
		maxValue: 29,
		labelFactor: 1.25,
		opacityArea: 0.75,
		dotRadius: 5,
		opacityCircles: 0.5,
		strokeWidth: 2,
		iconDim: 100
	};
	if('undefined' !== typeof options){
		for(var i in options){
			if('undefined' !== typeof options[i]){ settings[i] = options[i]; }
		}
	}
	var maxValue = Math.max(settings.maxValue, d3.max(data, function(i){return d3.max(i.map(function(o){return o.value;}))}));
	var allAxis = (data[0].map(function(i, j){return i.axis})),
		total = allAxis.length,
		radius = Math.min(settings.w/2, settings.h/2),
		Format = d3.format('%'),
		angleSlice = Math.PI * 2 / total;
	var rScale = d3.scale.linear()
		.range([0, radius])
		.domain([0, maxValue]);
	var svg = d3.select(id).append('svg')
		.attr('width',  settings.w + settings.margin.left + settings.margin.right)
		.attr('height', settings.h + settings.margin.top + settings.margin.bottom)
		.attr('id', 'malwareSpiderChart')
		.style('overflow', 'visible')
		.attr('class', 'radar'+id);
	var g = svg.append('g')
		.attr('transform', 'translate(' + (settings.w/2 + settings.margin.left) + ',' + (settings.h/2 + settings.margin.top) + ')');
	var axisGrid = g.append('g').attr('class', 'axisWrapper');
	var gradient1 = svg.append('defs')
	  .append('radialGradient')
	    .attr('id', 'radial-gradient1');
	gradient1.append('stop')
	    .attr('offset', '56%')
	    .attr('stop-color', '#0DDA17');
	gradient1.append('stop')
	    .attr('offset', '100%')
	    .attr('stop-color', '#008D12');
	var gradient2 = svg.append('defs')
	  .append('radialGradient')
	    .attr('id', 'radial-gradient2');
	gradient2.append('stop')
	    .attr('offset', '55%')
	    .attr('stop-color', '#A91F00');
	gradient2.append('stop')
	    .attr('offset', '85%')
	    .attr('stop-color', '#FF6800');
	var gradient3 = svg.append('defs')
	  .append('radialGradient')
	    .attr('id', 'radial-gradient3');
	gradient3.append('stop')
	    .attr('offset', '56%')
	    .attr('stop-color', '#350000');
	gradient3.append('stop')
	    .attr('offset', '93%')
	    .attr('stop-color', '#FF0000');
	gradient3.append('stop')
	    .attr('offset', '100%')
	    .attr('stop-color', '#E60000');
	var gradients = ['#C10000','#D65600','#297700'];
	axisGrid.selectAll('.levels')
	   .data(gradients)
	   .enter()
		.append('circle')
		.attr('class', 'gridCircle')
		.attr('r', function(d, i){return (radius/gradients.length*(gradients.length-i))*1.02;})
		.style('fill', function(d, i){var step = gradients.length-i; return 'url(#radial-gradient'+step+')';})
		.style('stroke', function(d, i){return d;})
		.style('stroke-width', '3px')
		.style('fill-opacity', 1);
	var axis = axisGrid.selectAll('.spiderchartAxis')
		.data(allAxis)
		.enter()
		.append('g')
		.attr('id', function(d, i){var stringLowerCase = d.toLowerCase(); return stringLowerCase + 'SpiderChartIcon';})
		.attr('class', 'spiderchartAxis');
	axis.append('line')
		.attr('x1', 0)
		.attr('y1', 0)
		.attr('x2', function(d, i){ return rScale(maxValue*1.065) * Math.cos(angleSlice*i - Math.PI/2); })
		.attr('y2', function(d, i){ return rScale(maxValue*1.065) * Math.sin(angleSlice*i - Math.PI/2); })
		.attr('class', 'line')
		.style('stroke', '#385277')
		.style('stroke-width', '2px')
		.style('stroke-opacity', 0.5);
	$('#allIcons').appendTo('#ransomwareSpiderChartIcon');
	d3.select("#malwareTypesTooltip").style('pointer-events', 'none');
	axis.append('rect')
		.attr('class', 'malwareTypesLegend')
		.attr('data-malwareType', function(d, i){return d.toLowerCase(); })
		.attr('width', settings.iconDim)
		.attr('height', settings.iconDim)
		.attr('x', function(d, i){ return rScale((maxValue*1.05) * settings.labelFactor) * Math.cos(angleSlice*i - Math.PI/2) - (settings.iconDim/2); })
		.attr('y', function(d, i){ return rScale((maxValue*1.05) * settings.labelFactor) * Math.sin(angleSlice*i - Math.PI/2) - (settings.iconDim/2); })
		.style('fill', 'none')
		.style('pointer-events', 'all')
		.on('mouseover', function(d,i) {
			newX =  rScale((maxValue*1.05) * settings.labelFactor) * Math.cos(angleSlice*(i) - Math.PI/2) - (settings.iconDim/2);
			newY =  rScale((maxValue*1.05) * settings.labelFactor) * Math.sin(angleSlice*(i) - Math.PI/2) - (settings.iconDim/2);
			$('#malwareTypesTooltip').html('');
			$('#malwareTypesTooltip').html('<strong class="title">'+d+'</strong><br>'+malwareTypesDefinitions[d]);
			$('#malwareTypesTooltip').css({'left':newX-(0.5*$('#malwareTypesTooltip').width()), 'top':newY-$('#malwareTypesTooltip').outerHeight()-5});
			$('#malwareTypesTooltip').fadeIn(40);
		})
		.on('mouseout', function(){
			$('#malwareTypesTooltip').fadeOut(40);
		})
		.attr('empty', function(d, i){
			var currX = rScale((maxValue*1.05) * settings.labelFactor) * Math.cos(angleSlice*i - Math.PI/2) - (settings.iconDim/2); 
			var currY = rScale((maxValue*1.05) * settings.labelFactor) * Math.sin(angleSlice*i - Math.PI/2) - (settings.iconDim/2);
			currEl = d.toLowerCase().split(' ')[0];
			$('#allIcons #'+currEl).attr('transform', 'translate('+currX+' '+currY+')');
			$('#allIcons #'+currEl).attr('style', 'cursor: hand; cursor: pointer;');
		});
	axis.append("text")
		.attr("class", "legend")
		.style("font-size", "12px")
		.style("font-weight", "bold")
		.style("fill", "#204C70")
		.attr("text-anchor", "middle")
		.attr("dy", "0.35em")
		.attr("x", function(d, i){ return rScale((maxValue*1.05) * settings.labelFactor) * Math.cos(angleSlice*i - Math.PI/2); })
		.attr("y", function(d, i){ return rScale((maxValue*1.05) * settings.labelFactor) * Math.sin(angleSlice*i - Math.PI/2)-(settings.iconDim/2); })
		.text(function(d){return d});
	var radarLine = d3.svg.line.radial()
		.interpolate('linear-closed')
		.radius(function(d) { return rScale(d.value); })
		.angle(function(d,i) {	return i*angleSlice; });
	radarLine.interpolate('cardinal-closed');
	var blobWrapper = g.selectAll('.radarWrapper')
		.data(data)
		.enter().append('g')
		.attr('class', 'radarWrapper');	
	blobWrapper
		.append('path')
		.attr('class', 'radarArea')
		.attr('d', function(d,i) { return radarLine(d); })
		.style('fill', function(d,i) { return 'black'; })
		.style('fill-opacity', settings.opacityArea);
	blobWrapper.append('path')
		.attr('class', 'radarStroke')
		.attr('d', function(d,i) { return radarLine(d); })
		.style('stroke-width', settings.strokeWidth + 'px')
		.style('stroke', 'black')
		.style('fill', 'none');
	blobWrapper.selectAll('.radarCircle')
		.data(function(d,i) { return d; })
		.enter().append('circle')
		.attr('class', 'radarCircle')
		.attr('r', settings.dotRadius)
		.attr('cx', function(d,i){ return rScale(d.value) * Math.cos(angleSlice*i - Math.PI/2); })
		.attr('cy', function(d,i){ return rScale(d.value) * Math.sin(angleSlice*i - Math.PI/2); })
		.style('stroke', function(d,i) { return 'black'; })
		.style('fill', function(d,i,j) { return '#00688C'; })
		.style('fill-opacity', 1);
	var blobCircleWrapper = g.selectAll('.radarCircleWrapper')
		.data(data)
		.enter().append('g')
		.attr('class', 'radarCircleWrapper');
	var axisGridTop = g.append('g').attr('class', 'axisWrapperTop');
	var threadLevels = ['clean', 'suspicious', 'malicious'];
	axisGridTop.selectAll('.axisLabel')
		.data(threadLevels)
		.enter().append('text')
		.attr('class', 'axisLabel')
		.attr('x', 10)
		.attr('y', function(d, i){return (-i*radius/threadLevels.length)-(radius/7)})
		.attr('dy', '0.4em')
		.style('font-size', '10px')
		.attr('fill', 'white')
		.text(function(d,i) { return d; });
}


var margin = {top: 100, right: 100, bottom: 100, left: 100},
    width = Math.min(700, window.innerWidth - 10) - margin.left - margin.right,
    height = Math.min(width, window.innerHeight - margin.top - margin.bottom - 20);




var signatureinfo = [0,0,5,0,0,0,0,0,0,0];
if(signatureinfo[9] == undefined){
	signatureinfo[9] = 0;
}
$.each(signatureinfo, function(k, v){
	if(v == 0){
		signatureinfo[k] = 7;
	}else{
		signatureinfo[k] = v + 10;
	}
});

var malwareTypes = [[
    {axis:'Ransomware',value:(signatureinfo[0])},
    {axis:'Spreading',value:(signatureinfo[1])},
    {axis:'Phishing',value:(signatureinfo[2])},
    {axis:'Banker',value:(signatureinfo[3])},
    {axis:'Trojan / Bot',value:(signatureinfo[4])},
    {axis:'Adware',value:(signatureinfo[5])},
    {axis:'Spyware',value:(signatureinfo[6])},
    {axis:'Exploiter',value:(signatureinfo[7])},
	{axis:'Evader',value:(signatureinfo[8])},
	{axis:'Miner',value:(signatureinfo[9])}
]];

var malwareTypesDefinitions = {
    'Ransomware':'Encrypts your personal files such as documents and pictures. In addition it may block access to your computer. In order to get back your file and access you have to pay a ransom.',
    'Spreading':'Spreads by infecting other files and other mediums (e.g. USB drive, Computers etc).',
    'Phishing':'Surreptitiously persuades the user to a certain action. Tricks the user into sharing sensitive information such as passwords, Credit Card keys and login information.' ,
    'Banker':'Modifies your e-banking transactions to steal money.',
    'Trojan / Bot':'Disguises its actual functionality. Allows third-parties to access the system (e.g. RAT). Bot: transforms infected systems into zombies and performs tasks such as DDoS or spaming.',
    'Adware':'Injects advertisements into your browser search results.',
    'Spyware':'Steals sensitive information such as login credentials and browser histories.',
    'Exploiter':'System executes code unintentionally.',
    'Evader':'Bypasses OS protections (e.g. disable security settings). Uses anti-reversing tricks (e.g. applies anti-debugging tricks). Obfuscates its behavior (e.g. uses non-standard tools) or data.',
    'Miner':"Uses the host's CPU to mine for crypto-currencies such as BitCoin, Ether or similar."
};
var radarChartOptions = {
  w: width,
  h: height,
  margin: margin
};

$(document).bind('loaded',function(){
	spiderChart(".radarChart", malwareTypes, radarChartOptions);
	$(document).trigger('spiderchartLoaded');
});




