  var apiArr = [];
  apiTable.find('.api').each(function(i){
    var text = $(this).text();
    if($(this).parents('ul').parents('ul').length == 0){
      if($.inArray(text, apiArr) == -1){
        $('#generateSigApi').append('<option value="'+text+'">'+text+'</option>');
      }
      apiArr.push(text);
    }
  });
  stringTable.find('.string').each(function(i){
    var text = $(this).html();
    $('#generateSigString').append('<option value="'+text+'">'+text+'</option>');
  });
  var generateSig = $('#generateSig');
  generateSig.show();
