$(document).on('click', '#generateSigInTextarea', function(){
  var $generateSigString = $('#generateSigString option:selected');
  var $generateSigApi = $('#generateSigApi option:selected');
  if($generateSigString.length > 0 || $generateSigApi.length > 0){
    var sigPython = '' +
    'def forwhicharch():\n' +
    '\treturn "windows"\n' +
    '\n' +
    'def forwhichevent():\n' +
    '\treturn "function"\n' +
    '\n' +
    'def id():\n' +
    '\treturn '+$('#generateSig .id').val()+'\n' +
    '\n' +
    'def desc():\n' +
    '\treturn "'+$('#generateSig .description').val()+'"\n' +
    '\n' +
    'source = []\n' +
    '\n' +
    'def event(data):\n' +
    '\n' +  
    '\tfoundAPI = False\n' +
    '\tfoundString = False\n';

    $generateSigString.each(function(i){
      sigPython += ''+
      '\tfoundString'+i+' = False\n';
    });

    if($generateSigApi.length > 0){
      sigPython += ''+
      '\tchain = data["apichain"].lower()\n';
    };

    $generateSigApi.each(function(i){
      if(i == 0){
        sigPython += '\tif ';
      }else{
        sigPython += '\\\n\tand ';
      }
      var text = $(this).text();
      text = text.split('\\').join('\\\\');

      sigPython += 'chain.find("' + $(this).text().toLowerCase() + '") != -1';
    });

    if($generateSigApi.length > 0){
      sigPython += ''+
      ':\n'+
      '\t\tfoundAPI = True\n' +
      '\telse:\n' +
      '\t\treturn False\n' +
      '\n';
    };

    if($generateSigString.length > 0){
      sigPython += ''+
      '\tfor instr in data["body"]:\n';
    };

    $generateSigString.each(function(i){

      var text = $(this).text();
      text = text.split('\\').join('\\\\');
      sigPython += ''+
      '\n\t\tif instr["string"].find("'+text+'") != -1:\n'+
      '\t\t\tfoundString'+i+' = True';

    });

    $generateSigString.each(function(i){
      if(i == 0){
        sigPython += '\n\t\tif ';
      }else{
        sigPython += ' and ';
      }
      sigPython += 'foundString'+i;
    });

    if($generateSigString.length > 0){
      sigPython += ':\n\t\t\tfoundString = True\n' +
      '\n';
    };

    if($generateSigString.length == 0){
      sigPython += '\tif foundAPI:\n';
    }else if($generateSigApi.length == 0){
      sigPython += '\tif foundString:\n';
    }else{
      sigPython += '\tif foundString and foundAPI:\n';
    }
    sigPython += '' +
    '\t\tsource.append(("Code function", data["currentpath"], data["sourceid"] + " " + data["apichain"], data["sourceid"]))\n' +
    '\n' +
    '\treturn False\n' +
    '\n' +
    'def endmatch(data):\n' +
    '\treturn len(source) > 0\n' +
    '\n' +  
    'def getSources():\n' +
    '\treturn source\n';
  }else{
    sigPython = "Please select some API's or Strings to generate a Signature";
  }
  $('#generateSigTextarea').val(sigPython);
});
