$(document).on('click', '.lookupFunction', function(){
  $('.overlay').hide();
  var lookupFunction = $('#lookupFunction');
  var lookupFunctionContent = $('#lookupFunction #lookupFunctionContent');
  lookupFunctionContent.html('');
  lookupFunction.show();
  var ajaxPostData = {};
  var $this = $(this);
  var apiHash, stringHash, opCodeHash;
  var functionId = $this.parent().parent().find('.accordion-toggle').data('target');
  functionId = functionId.replace('#body_', '');
  var checkHashes ={
    'api_hash':functionsArr[functionId]['api_hash'],
    'string_hash':functionsArr[functionId]['string_hash'],
    'op_code_hash':functionsArr[functionId]['op_code_hash']
  };

  $.each(checkHashes, function(key, value){
    if(value == 'd41d8cd98f00b204e9800998ecf8427e'){
      checkHashes[key] = '';
    }
  });

  $.ajax({
    url:"http://functiondb.joesecurity.org/index.php/api/lookupFunction",
    dataType: 'JSONP',
    data: checkHashes,
    type: "GET",
    success:function(response){
      functions = $.parseJSON(response);
      if(functions.length == 0){
        lookupFunctionContent.append('No similar functions found');
        lookupFunction.css("top", (($(window).height() - $('#postData').height())/2)-30);
        lookupFunction.css('margin-top', $this.outerHeight());
      }else{
        var hasApi = false;
        var hasString = false;
        var hasOpCode = false;
        $.each(functions, function(i, functionObj){
          if(checkHashes['api_hash'] == functionObj['api_hash']){
            hasApi = true;
          }
          if(checkHashes['string_hash'] == functionObj['string_hash']){
            hasString = true;
          }
          if(checkHashes['op_code_hash'] == functionObj['op_code_hash']){
            hasOpCode = true;
          }
        });
        tableString = '<table style="width:100%"><thead><tr>'+
                        '<th>Analysis ID</th>'+
                        '<th>File Name</th>'+
                        '<th>Function Name</th>'+
                        '<th>Comment</th>'+
                        (hasApi ? '<th>Api Hash</th>' : '')+
                        (hasString ? '<th>String Hash</th>' : '')+
                        (hasOpCode ? '<th>Op Code Hash</th>' : '')+
                        '<th>Analysis Detection</th>'+
                        '<th>Analysis Score</th>'+
                        '<th>Function Detection</th>'+
                      '</tr></thead><tbody>';

        $.each(functions, function(i, functionObj){

          tableString += '<tr>';
          tableString += '<td>'+functionObj['analysis_id']+'</td>';
          tableString += '<td>'+functionObj['name']+'</td>';
          tableString += '<td>'+functionObj['function_name']+'</td>';
          tableString += '<td>'+functionObj['comment']+'</td>';
          tableString += (checkHashes['api_hash'] == functionObj['api_hash'] ? '<td class="same-hash">'+functionObj['api_hash']+'</td>' : (hasApi ? '<td></td>' : ''));
          tableString += (checkHashes['string_hash'] == functionObj['string_hash'] ? '<td class="same-hash">'+functionObj['string_hash']+'</td>' : (hasString ? '<td></td>' : ''));
          tableString += (checkHashes['op_code_hash'] == functionObj['op_code_hash'] ? '<td class="same-hash">'+functionObj['op_code_hash']+'</td>' : (hasOpCode ? '<td></td>' : ''));
          tableString += '<td>'+functionObj['analysis_detection_status']+'</td>';
          tableString += '<td>'+functionObj['analysis_score']+'</td>';
          tableString += '<td>'+functionObj['function_detection_status']+'</td>';
          tableString += '</tr>';

        });
        tableString += '</tbody></table>';
        lookupFunctionContent.append(tableString);
        lookupFunction.css("top", (($(window).height() - $('#postData').height())/2)-30);
        lookupFunction.css('margin-top', $this.outerHeight());
      }
    },
    error:function(){
      console.log("Lookup Function Call Error.");
    }
  });
});

