$('.svgGraph').each(function(){
	if($(this).find('svg').length > 0){
		var edgesArray = [];
		var nodeArray = [];
		var targetId = $(this).data('targetid');
		maxZoom = (parseInt($('#graphWrapper_'+targetId+' svg').attr('height')) / $('#graphWrapper_'+targetId).height())+40;
		panZoomGraph[targetId] = svgPanZoom('#graphWrapper_'+targetId+' svg', {
			zoomEnabled: true,
			controlIconsEnabled: true,
			fit: false,
			center: false,
			maxZoom: Math.round(maxZoom),
			beforePan: function(oldPan, newPan) {
			  setTimeout(function(){
			    updateSvgBoundingBox();
			    setTimeout(function(){
			      updateSvgBoundingBox();
			    }, 50);
			  }, 30); 
			},
			beforeZoom: function(oldPan, newPan) {
			  setTimeout(function(){
			    updateSvgBoundingBox();
			    setTimeout(function(){
			      updateSvgBoundingBox();
			    }, 70);
			  }, 50);
			}
		});
		hideShowNodeEdges[targetId] = {};

		$(this).find('.edge title').each(function(){
	        hideShowNodeEdges[targetId][$(this).text()] = $(this).parent();
	    });
	    $(this).find('.node title').each(function(){
	        hideShowNodeEdges[targetId][$(this).text()] = $(this).parent();
	    });
	    
			var graph = graphs['graph'+targetId];
		
		var hideNodes = $.grep(graph.nodes, function(node){ 
			return node.hide == 'true'; 
		});
		$.grep(graph.links, function(link){
			$.grep(hideNodes, function(hideNode){  
				if(link.id.indexOf(hideNode.id) >= 0){
					var sourceTarget = link.source+'->'+link.target;
					edgesArray.push(sourceTarget);
				};
			});
		});
		$.grep(hideNodes, function(hideNode){
			nodeArray.push(hideNode.id);
		});
		hideShowNodeEdges[targetId]['edgesArray'] = edgesArray;
		hideShowNodeEdges[targetId]['nodeArray'] = nodeArray;
	    $(this).prepend('<div class="showHideGraphEdges shown">Hide Nodes/Edges</div>');
		$(this).prepend('<div class="showLegend">Show Legend</div>');
	}else{
	  $(this).hide();
	}
});


