var distributePieGraphBox = function(){
	var mainWidth = $('#main').width();
	var graphPieNmbr = 0;
	var lastIdOfGraphCreatedInside;
	$('.graphPie').each(function(){
		var id = $(this).data('id');
		if(lastIdOfGraphCreatedInside != id){
			graphPieNmbr++;
		}
		lastIdOfGraphCreatedInside = id;
	});
	var pieGraphBoxlength = $('.pieGraphBox').length / graphPieNmbr;
	var pieGraphBoxWidth = $('.pieGraphBox').width();
	var totalBoxWidth = pieGraphBoxlength * pieGraphBoxWidth;
	var gapWidth = ((mainWidth - totalBoxWidth) / (pieGraphBoxlength - 1)) - 1;

	$('.graphPie').each(function(i){
		var graphID = $(this).attr('id');
		$(this).find('.pieGraphBox').each(function(i){
			if(i < pieGraphBoxlength-1){
				$(this).css("margin-right",gapWidth);
			};
		});
	});
};
distributePieGraphBox();
$(window).resize(function(){
	distributePieGraphBox();
	$('.svgGraph').each(function(){
		var targetId = $(this).data('targetid');
		panZoomGraph[targetId].resize();
		panZoomGraph[targetId].fit();
		panZoomGraph[targetId].center();
	});
	$('.cfgGraph').each(function(){
		var functionId = $(this).data('functionid');
		if(panZoomGraph[functionId] != undefined){
			panZoomGraph[functionId].resize();
			panZoomGraph[functionId].fit();
			panZoomGraph[functionId].center();
		}
	});
	$('.callGraph').each(function(){
		var targetId = $(this).data('targetid');
		panZoomGraph[targetId+"callgraph"].resize();
		panZoomGraph[targetId+"callgraph"].fit();
		panZoomGraph[targetId+"callgraph"].center();
	});	
});
