$(document).on('click', '.behaviorJump', function(){

  var section = $(this).data('section');
  var activity = $(this).data('activity');
  var pidmd5 = $(this).data('pidmd5');
  var id = $(this).data('id');
  var iswindows = $(this).data('iswindows');

  if(section == 'sectionLoaded'){
    if(iswindows){
      section = 'sectionLoadedW';
    }else{
      section = 'sectionLoadedP';
    }
  }

  if($('#'+pidmd5).next().find('*[data-activity="'+section+'"]').parent().hasClass('collapsed')){
    $('#'+pidmd5).next().find('*[data-activity="'+section+'"]').click();
  }

  var activityArr = activity.split('activities');
  var activitySection = $('#'+pidmd5).next().next().find('#'+activityArr[0]+'-activities');
  var lastSection = activitySection.find('a[data-activity="'+section+'"]');
  if(lastSection.parent().hasClass('collapsed')){
    lastSection.click();
  }

  var element = $('#'+id);

  if(element.length == 0){
    element = $('#'+pidmd5);
    if(element.find('.accordion-wrapper').hasClass('collapsed')){
      element.find('.accordion-toggle').click();
    }
  }
  
  if(element.hasClass('onlywindows')){
    $('#'+pidmd5).next().find('*[data-activity="'+section+'"]').closest('.activity-body').prev().find('.btn.show-all').click();
  }

  $('.foundThroughSearch').removeClass('foundThroughSearch');
  
  if(element.length != 0){
    element.addClass('foundThroughSearch');
  }

  $('html, body').animate({
      scrollTop: element.offset().top-200
  }, 400);
});



  




