   var setCurrentBgImage = function(currentPx){
    var imageToPick;
    $('#screenshotx .slideshow img:not(.slideshowProcess)').each(function(i){
      var width = parseInt(slideshowNavWidth/dateImgArr.length);
      var imageWidth = (i+1)*width;
      if(currentPx <= imageWidth && currentPx >= imageWidth - width){
        imageToPick = $(this);
      }

    });
    var newImageSrc = imageToPick.attr('src');
    $('#deviceScreen').attr('src', newImageSrc);
   }

