function selectText(element, isid) {
    var doc = document, range, selection, text;
    if(isid === true){
      text = doc.getElementById(element);
    }else{
      text = element;
    }
    if (doc.body.createTextRange) { //ms
        range = doc.body.createTextRange();
        range.moveToElementText(text);
        range.select();
    } else if (window.getSelection) { //all others
        selection = window.getSelection();        
        range = doc.createRange();
        range.selectNodeContents(text);
        selection.removeAllRanges();
        selection.addRange(range);
    }
}
function scrollToElementTop(element, time){
  time = time | 400;
  var stop = $(element).offset().top;
  var navbarsize = $('.navbar').height();   
  $('html, body').animate({
      scrollTop: stop  - navbarsize - 120 
  }, time);
}

var adr_history = [], adr_pos = -1, adr_pos_nav = -1;
function buildDisasmHistory(){
  var list = '';
  for( var line in adr_history){
    var cl = '';
    if(line == (adr_pos_nav)){
      cl = 'current';
    }else if( line > adr_pos_nav){
      cl = 'mute';
    }
    list += '<li class="'+cl+'"><a href="#" data-target="'+line+'" class="disasm-jump">'+adr_history[line].addr +'</a></li>';
  }
  return list;
}
function updateDisasmHistory(){
  $('#disasm-history').html(buildDisasmHistory());
  $('.disasm-jump').unbind('click');
  $('.disasm-jump').bind('click', function(event){
    adr_jump($(this).attr('data-target'));
    event.preventDefault();
  });
  
}
function adr_reset(){
  adr_pos_nav = -1;
  adr_pos = -1;
  adr_history = [];
  $('#disasm-history').html('');
}
function adr_go_fwd(){  
  adr_jump(adr_pos_nav+1);
}
function adr_go_back(){
  adr_jump(adr_pos_nav-1);
}

function adr_jump(num){
  adr_pos = Math.min(adr_history.length-1, Math.max(num, 0));
  adr_pos_nav = adr_pos;
  if(adr_history.length > 0){
    var element = document.getElementById(adr_history[adr_pos].id);
    scrollToElementTop(element);
    if(adr_history[adr_pos].id.indexOf("graphWrapper") == -1){

      selectText(element, false);
    }else{
      adr_pos = adr_history.length-1;
    }
    updateDisasmHistory();
  }
}

function adr_new_goto(event){
  if(adr_pos == -1 || adr_history[adr_pos].addr != event.target.addr){
    adr_pos += 2;
    adr_pos_nav = adr_pos;
    
    if($(event.target).attr('data-line') != undefined){

      var id = $(event.target).attr('data-line');
      var addr = id.substr(id.lastIndexOf('_')+1, id.length); 
      adr_history[adr_pos-1] = {'id': id, 'addr': addr};
    }
    var graphLink = false;
    if($(event.target).hasClass('graphLink')){
      var targetId = $(event.target).closest('.svgGraph').data('targetid');
      var id = 'graphWrapper_'+targetId;
      var str = $(event.target).text();
      var result = str.substr(str.lastIndexOf("_")+1);
      var addr = 'Graph ' + targetId+'<br>'+ result;
      adr_history[adr_pos-1] = {'id': id, 'addr': addr, 'class': 'graphJump'};
        graphLink = true;
    }
    id = event.target.href.substr(event.target.href.lastIndexOf('#')+1);    
    var addr = id.substr(id.lastIndexOf('_')+1, id.length); 
      adr_history[adr_pos] = {'id': id, 'addr': addr};
    if(adr_history.length > adr_pos-1){
      adr_history = adr_history.slice(0, adr_pos+1);
    }
  }
  updateDisasmHistory();
}
function find_parent(addr){
  for(var f in disasm.functions){
    if($.inArray(addr,disasm.functions[f])!=-1){
      return f;
    }
  }
  return 'error';
}

function goto_address(event, history) {
if(!reportTourElementSelecting){
  // Get href target
  var target = event.target.href.substring(event.target.href.indexOf('#')+1);
  if(typeof disasm[target]=='undefined'){
    $(this).replaceWith('<span class="muted">'+$(this).html()+'</span>');
    alert("Adress not found");
    event.preventDefault();
    return 0;
  }
  if(typeof history == 'undefined' && ! ($(this).hasClass('no-history') || $(this).hasClass('adrjump')  )){
    adr_new_goto(event);
  }
  var parent = find_parent(target);
  if($('#body_'+parent).length == 0){
    $(this).replaceWith('<span class="muted">'+$(this).html()+'</span>');
    alert("Adress not found");
    event.preventDefault();
    return 0;
  }
  if(!$('#body_'+parent).hasClass('in')){
    $('#body_'+parent).prev().find('a').click();
    checkLinks($('#body_'+parent));
  }
  var time = 0;
  if($.browser.msie){
    time = 30;
  }
  setTimeout(function(){      
    var stop = $('#'+target).offset().top;
    var navbarsize = $('.navbar').height();
    window.scrollTo(0,stop - navbarsize - 120);
    selectText(target, true);
  }, time);

  $('#body_'+parent).prev().find('.accordion-wrapper').removeClass('collapsed').addClass('expanded');
  event.preventDefault();
}
}

function compare(a,b) {
  if (Number(a.tick) < Number(b.tick))
    return -1;
  if (Number(a.tick) > Number(b.tick))
    return 1;
  return 0;
}

function buildChronoTable(id){
  if(typeof chrono[id]=='undefined' || chrono[id].visible=='1'){
    return '';
  }
  var data=chrono[id];
  var result='<table class="table table-bordered joeTable"><thead>' +
  '<th width="20%">Operation</th>' +
  '<th width="45%">Data</th>' +
  '<th width="15%">Completion</th>' +
  '<th width="7%">Ret</th>' +
  '<th width="8%">Symbol</th>' +
  '<th width="5%">Time</th>' +
  '</thead><tbody>';

  for(var i in data){
    var tr='<tr class="isnotwindows" >';
    if(data[i].iswindows=='1'){
      tr='<tr class="onlywindows" style="display:none;">';
    }
    result += tr;
    result += '<td>' + data[i].type + '</td>';
    result += '<td style="word-break: break-all;">' + bolderizeUpercaseWordsThatEndWithDoublePoints(escapeHtmlWithoutWbr(data[i].path)) + '</td>';
    result += '<td>' + data[i].status + '</td>';
    result += '<td><a href="#' + data[i].funcid + '" class="adrjump">' + data[i].ret + '</a></td>';
    result += '<td>' + data[i].symbol + '</td>';
    result += '<td>' + data[i].tick + '</td>';
    result += '</tr>';
  }
  chrono[id]['visible']='1';
  return result + '</tbody></table>';
}

function isSectionEmpty(process,section){
  if(typeof behavior[process]=='undefined' || typeof behavior[process][section]=='undefined' ||  behavior[process][section].visible=='1'){
    return true;
  }
  var data=behavior[process][section].activities;
  var len=0;
  for(var a in data){
    if(typeof data[a].items !='undefined'){
      len +=data[a].items.length;
    }
  }
  return len==0;
}
function buildSectionActivities(process,section){
  if(typeof behavior[process]=='undefined' || typeof behavior[process][section]=='undefined' ||  behavior[process][section].visible==true || isSectionEmpty(process,section)){
    return '';
  } 
  
  var data=behavior[process][section];

  // Check if there are only hidden activities
  var totalActivities = 0;
  var isWindowsActivities = 0;
  var isWindowsSubActivities = 0;

  for(var i in data.activities){
    if(data.activities[i].items.length > 0){
      totalActivities++;
      if(data.activities[i]['iswindows'] == '1' && (data.activities[i]['show_always'] != '1' && data.activities[i]['is_important'] != '1')){
        isWindowsActivities++;
      }
    }
    for(var item in data.activities[i].items){
      if(data.activities[i].items[item]['iswindows'] == '1'){
        isWindowsSubActivities++;
      }
    }
  }

  var isCollapsed1 = '';
  if(totalActivities == isWindowsActivities){
    isCollapsed1 = 'collapsed';
  }else{
    isCollapsed1 = 'expanded';
  }

  result='<div class="joeHeadingBoxWithButton hd joeCollapsable '+isCollapsed1+'">';
  if(data['no_button'] !='1' && (isWindowsActivities > 0 || isWindowsSubActivities > 0)){
    result +='<div class="pull-right">'+
    '<a class="btn hide-all" href="#'+section+'-activities" style="display:none;"'+
    'data-process="'+process+'" '+
    'data-section="'+section+'">Hide Windows behavior</a>'+
    '<a class="btn show-all" href="#'+section+'-activities"'+
    'data-process="'+process+'" '+
    'data-section="'+section+'">Show Windows behavior</a></div>'
  }
  result+='<a class="accordion-toggle" href="#'+section+'-activities">';
  result +='<h4  class="joeHeading">'+data.title+'</h4></a></div>';

  if(totalActivities == isWindowsActivities){
    result += '<div style="height: 0px;" id="'+section+'-activities" class="activity-body collapse bd accordion-body">';
  }else{
    result += '<div id="'+section+'-activities" class="activity-body in collapse bd accordion-body">';
  }
  
  if(totalActivities == isWindowsActivities){
    result += '<div class="joeBorderBox hiddenWindowsActivityNotification" style="padding: 6px 6px;">There is hidden Windows Behavior. Click on <strong>Show Windows Behavior</strong> to show it.</div>';
  }

  // Check END

  for(var i in data.activities){
    result += buildActivity(process,section,i);
  } 
  return result+'</div>';
}
function wordwrap( str,width,brk,cut ) { 
    brk=brk || '\n';
    width=width || 75;
    cut=cut || false; 
    if (!str) { return str; } 
    var regex='.{1,' +width+ '}(\\s|$)' + (cut ? '|.{' +width+ '}|.+$':'|\\S+?(\\s|$)'); 
    return str.match( RegExp(regex,'g') ).join( brk ); 
}
function buildActivity(process,section,activity){
  if(typeof behavior[process]=='undefined' || typeof behavior[process][section]=='undefined' || typeof behavior[process][section].activities[activity]=='undefined'){
    return '';
  } 
  var data=behavior[process][section].activities[activity]; 
  var bodyId=activity+behavior[process]["id"];
  if( !(data.items.length > 0)){
    return '';
  } 
  var wnd='class="joeDetection malicious joeCollapsable"';
  var bodyWnd='';
  if(typeof data["iswindows"] !='undefined' && data["iswindows"]=='1' ){
    wnd='class="joeDetection info onlywindows hd joeCollapsable"';
    bodyWnd='onlywindows bd accordion-body';
    if(behavior[process][section].showwindows !=true){
      wnd +=' style="display:none;"'
    }
  } 
  if(typeof data["show_always"] !='undefined' && data["show_always"]=='1'){
    wnd='class="joeDetection info hd joeCollapsable"';
    bodyWnd='';
  }
  if(typeof data["is_important"] !='undefined' && data["is_important"]=='1'){
    wnd='class="joeDetection malicious joeCollapsable"';
    bodyWnd='';
  }
  
  var result='<div '+ wnd +' >'+
  '<a href="#'+bodyId+'" '+
  'class="accordion-toggle" '+
  'data-process="'+process+'" '+
  'data-section="'+section+'" '+
  'data-activity="'+activity+'" >'+
  '<h5 class="joeHeading">'+data.title+'</h5></a></div>'+
  '<div class="'+bodyWnd+' bd accordion-body collapsed collapse" id="'+bodyId+'"></div>';
  return result;
}
function buildActivityTable(process,section,activity){

  if(typeof behavior[process]=='undefined' || typeof behavior[process][section]=='undefined' || typeof behavior[process][section].activities[activity]=='undefined' || behavior[process][section].activities[activity].visible=='1'){
    return '';
  } 

  var data=behavior[process][section].activities[activity];
  var result='<table class="table table-bordered joeTable"><thead>';
  for(var i in data.table){var width='';
    if(typeof data.table_width !='undefined'){
      width='width="'+data.table_width[i]+'"';
    }
    result +='<th '+width+'>'+data.table[i]+'</th>';
  } 
  result +='</thead><tbody>'; 
  for(var i in data.items){
    var tr='<tr class="isnotwindows" ';
    if(data.items[i].iswindows=='0'){
      if(data.items[i].id!=''){
        tr += 'id="'+data.items[i].id+'"';
      } 
      tr += ' >';
    }
    if(data.items[i].iswindows=='1'){
      tr='<tr class="onlywindows"';     
      if(behavior[process][section].showwindows !='1'){
        tr +=' style="display:none;"';
      }
      if(data.items[i].id!=''){
        tr += 'id="'+data.items[i].id+'"';
      } 
      tr +=' >';
    }
    if(typeof data["show_always"] !='undefined' && data["show_always"]=='1'){
      tr='<tr ';
      if(data.items[i].id!=''){
        tr += 'id="'+data.items[i].id+'"';
      } 
      tr +=' >';
    }
    result +=tr;
    for(var j in data.items[i].fields){

      if(data.table[j] == 'Value' || data.table[j] == 'Data Hex' || data.table[j] == 'Data ASCII'){
        var joeFontMono = 'joeFontMono';
      }else{
        var joeFontMono = '';
      }

      if(typeof data.items[i].fields[j]=='object'){
        var x=data.items[i].fields[j]
        result +='<td class="'+joeFontMono+'"><a class="'+x.class+'" href="'+x.href.split(' ')[0]+'" >'+escapeHtml(x.text)+'</td>';
      } else {
        result +='<td class="'+joeFontMono+'">'+escapeHtml(data.items[i].fields[j])+'</td>';
      }
    }
    result +='</tr>';
  }
  behavior[process][section].activities[activity].visible='1';
  return result + '</tbody></table>';
}





