function expandAccordion(event, accordionToggle) {
	


  event.preventDefault();
  var id = accordionToggle.attr('href');

  if (id == undefined){
    id = accordionToggle.data('target');
  } 


  // If there are mutliple elements with same id
  try{
		if($('[id="'+id.substring(1)+'"]').length == 1){
			var $bodyToExpand = $(id);
		}else{
			var $bodyToExpand = accordionToggle.closest('.joeCollapsable').next();
		}

	  if(accordionToggle.parent().hasClass('collapsed')){
	    checkLinks(accordionToggle.closest('.activity-head').next());
	    accordionToggle.parent().removeClass('collapsed');
	    accordionToggle.parent().addClass('expanded');
	    $bodyToExpand.height('auto');
	    $bodyToExpand.addClass('in');
	    if($bodyToExpand.hasClass('function-toggle')){
	    	$bodyToExpand.trigger('show');
	    }
	  }else{
	    accordionToggle.parent().removeClass('expanded');
	    accordionToggle.parent().addClass('collapsed');
	    $bodyToExpand.height('0px');
	    $bodyToExpand.removeClass('in');
	  }
  } catch(b){}
}


