/* 	------------------------------------ SEARCH -----------------------------------------
	-------------------------------------------------------------------------------------
	------------------------------------ START ------------------------------------------ */

var searchTerm = 'emptySearchTerm';
var searchTermEscaped = 'emptySearchTerm';
var currentJson = undefined;
var chronoIndex = -1;
var disasmIndex = -1;
var lastSection = undefined;
var navbarsize = $('.navbar').height();
var searchResultIndex = 0;
var sectionIndex = 0;
var maxResultsPerSection = 50;
var endThisSearch = false;

function compare(a,b) {
  if (Number(a.tick) < Number(b.tick))
    return -1;
  if (Number(a.tick) > Number(b.tick))
    return 1;
  return 0;
}

if (typeof chrono !== 'undefined') {
	for (var key in chrono) {
	    if (chrono.hasOwnProperty(key)) {
	        chrono[key].sort(compare);
	    }
	}
}

ObjectValues = function (v, k) {
	if(sectionIndex < maxResultsPerSection){
		if (typeof v == "object") {
			for (var kp in v) {
				if(endThisSearch){
					return false;
				}
				if (Object.hasOwnProperty.call(v, kp)) {
					ObjectValues(v[kp], k != undefined ? k + "." + kp : kp);
				}
			}
		} else {
			v = String(v);
			if (v !== "undefined") {
				var value = v.toLowerCase();
				value = value.replace(/\r?\n|\r|\t|[^\w\s\<\>\{\}\.]| /ig, '');
				if (value.indexOf(searchTermEscaped) >= 0) {
					var keyArray = k.split('.');
					if (currentJson == 'behavior') {
						if(keyArray[keyArray.length - 1] != 'href' && keyArray[keyArray.length - 1] != 'title'){
							var currentSection = $('#'+keyArray[0] + ' #' + keyArray[1] + '-' + keyArray[2]).find('[data-activity="' + keyArray[3] + '"]');
							if(currentSection.length != 0){
								if(keyArray[0] + keyArray[1] + keyArray[2] + keyArray[3] == lastSection){
										behaviorIndex++;
								}else{
										behaviorIndex = 0;
								}
								// var dataPos = currentSection.data("pos");
								var dataPos = currentSection.find("[data-pos]");
								dataPos = dataPos.data('pos');
								dataPos = parseInt(dataPos);
								// Add 1 Elements to make sure it gets the right one..
								dataPos = dataPos + 1;
								var context = getContext(dataPos);
								$('#searchResultsBehavior').append(generateSearchResultItem(v, behaviorIndex, context, currentJson, k));
								$('#searchResultsBehavior').show(); 
								lastSection = keyArray[0] + keyArray[1] + keyArray[2] + keyArray[3]; 
								searchResultIndex++; 
								sectionIndex++;
							}     	
						}
					} else if (currentJson == 'chrono') {
						var currentSection = keyArray[0];
						if(currentSection == lastSection){
							chronoIndex++;
						}else{
							chronoIndex = 0;
						}
						if(currentSection.length != 0 && keyArray[2] != 'funcid'){
							var dataPos = $('#' + keyArray[0]).prev().find(".accordion-toggle");
							dataPos = dataPos.data('pos');
							dataPos = parseInt(dataPos);
							dataPos = dataPos + 1;
							// Add 1 Elements to make sure it gets the right one..

							var context = getContext(dataPos);
							$('#searchResultsChrono').append(generateSearchResultItem(v, chronoIndex, context, currentJson, k));
							$('#searchResultsChrono').show();
							lastSection = currentSection;
							searchResultIndex++;
							sectionIndex++;
						}
					} else if (currentJson == 'disasm') {

						if(keyArray[0] != 'instr'){
							var currentSection = '';
							if(keyArray[0] == 'functions'){
								currentSection = keyArray[1];
							}else{
								currentSection = disasm['instr'][keyArray[0]];
							}
							if(keyArray[3] != 'name'){
								if(currentSection == lastSection){
									disasmIndex++;
								}else{
									disasmIndex = 0;
								}
							}
							if($('#body_' + currentSection).length != 0){
								var context = getContext($('#body_' + currentSection).find("[data-pos]").data('pos'));
								$('#searchResultsDisasm').append(generateSearchResultItem(v, disasmIndex, context, currentJson, k));
								$('#searchResultsDisasm').show();
								lastSection = currentSection;
								searchResultIndex++;
								sectionIndex++;
							}
						}
						
					}
				}
			}
		}
	}else{
		sectionIndex = 0;
		endThisSearch = true;
		return false;
	}
};

// Find Results of search inside of the page
$(document).on('click', '.searchJump', function(e){
	$this = $(this);
	// Show last three clicked search results in different colors
	$('.secondLastClickedSearchResult').removeClass('secondLastClickedSearchResult').addClass('clickedSearchResult');
	$('.lastClickedSearchResult').removeClass('lastClickedSearchResult clickedSearchResult').addClass('secondLastClickedSearchResult');
	$this.parent().removeClass('secondLastClickedSearchResult clickedSearchResult').addClass('lastClickedSearchResult');
	$('.foundThroughSearch').removeClass('foundThroughSearch');
	if($this.data('json') == 'behavior'){
		var key = $this.data('key');
		var keyArray = key.split('.');
		var $sectionToOpen = $('#'+keyArray[0] + ' #' + keyArray[1] + '-' + keyArray[2]).find('[data-activity="' + keyArray[3] + '"]');
		var iswindows = behavior[keyArray[0]][keyArray[1]][keyArray[2]][keyArray[3]][keyArray[4]][keyArray[5]]['iswindows'];
		// Only show windows behavior if operation is found in windows behavior
		if(typeof iswindows !='undefined' && iswindows=='1' ){
			if($('#'+keyArray[0] + ' #' + keyArray[1] + '-' + keyArray[2]).parent().find('.hide-all').css('display') == 'none'){
				$('#'+keyArray[0] + ' #' + keyArray[1] + '-' + keyArray[2]).parent().find('.show-all').click();
			}
		}
		// Render the elements
		expandAllParents($sectionToOpen);
		// Make sure search over table titles, as well as in table content is possible
		$elementToOpen = $('#'+keyArray[3]+keyArray[0]+' td:contains("'+searchTerm+'"):eq('+ $this.data('index') +')');
		$elementToOpen2 = $('#'+keyArray[3]+keyArray[0]+' th:contains("'+searchTerm+'"):eq('+ $this.data('index') +')');
		if($elementToOpen.length == 0){
			$elementToOpen = $elementToOpen2;
		}
		if(searchResultsErrorHandling($elementToOpen, $this) == 'error'){
			return
		}
		$elementToOpen.addClass('foundThroughSearch');
		var stop = $elementToOpen.offset().top;
		$("html, body").animate({ scrollTop: stop - navbarsize - 130}, 200);

	}else if($this.data('json') == 'chrono'){
		var key = $this.data('key');
		var keyArray = key.split('.');
		var $sectionToOpen = $('#'+keyArray[0]).prev().find('.accordion-toggle');
		expandAllParents($sectionToOpen);
		// Only show windows behavior if operation is found in windows behavior
		var iswindows = chrono[keyArray[0]][keyArray[1]]['iswindows'];
		if(typeof iswindows !='undefined' && iswindows=='1' ){
			if($('#'+keyArray[0]).prev().find('.hide-all-chrono').css('display') == 'none'){
				$('#'+keyArray[0]).prev().find('.show-all-chrono').click();
			}
		}
		// Find Element in corresponding section
		$searchableElementsChrono = $('#'+keyArray[0] + ' td, #'+keyArray[0] + ' th, #'+keyArray[0] + ' a').filter(function() {
			return this.childNodes.length >= 1 && (this.firstChild.nodeType === 3|| this.lastChild.nodeType === 3 || this.firstChild.tagName == 'WBR' || this.firstChild.tagName == 'BR' || this.lastChild.tagName == 'WBR' || this.lastChild.tagName == 'BR');
		});
		searchResults = $searchableElementsChrono.filter(":contains('"+searchTermEscaped+"')");
		searchResults = searchResults.eq($this.data('index'));
		if(searchResultsErrorHandling(searchResults, $this) == 'error'){
			return
		}
		searchResults.addClass('foundThroughSearch');
		var stop = searchResults.offset().top;
		$("html, body").animate({ scrollTop: stop - navbarsize - 130}, 200);
	}else if($this.data('json') == 'disasm'){

		var key = $this.data('key');
		var keyArray = key.split('.');
		var sectionName = '';
		if(keyArray[0] == 'functions'){
			sectionName = keyArray[1];
		}else{
			sectionName = disasm['instr'][keyArray[0]];
		}
		expandAllParents($('#body_'+sectionName));
		// Find Element in corresponding section

		$elementToOpen = $('#body_'+sectionName + ' .jsonSearch *').filter(function() {
			return this.childNodes.length >= 1 && (this.firstChild.nodeType === 3|| this.lastChild.nodeType === 3 || this.firstChild.tagName == 'WBR' || this.firstChild.tagName == 'BR' || this.lastChild.tagName == 'WBR' || this.lastChild.tagName == 'BR');
		});

		$elementToOpen = $elementToOpen.filter(":contains('"+searchTermEscaped+"')");
		$elementToOpen = $elementToOpen.eq($this.data('index'));

		if(searchResultsErrorHandling($elementToOpen, $this) == 'error'){
			return
		}
		$elementToOpen.addClass('foundThroughSearch');
		var stop = $elementToOpen.offset().top;
		$("html, body").animate({ scrollTop: stop - navbarsize - 130}, 200);

	}else if($this.data('json') == 'html'){
		var originalPos = $this.data('index');
		htmlResultElement = $("#main *[data-pos=" + originalPos + "]");
		if(searchResultsErrorHandling(htmlResultElement, $this) == 'error'){
			return
		}
		expandAllParents(htmlResultElement);
		if(htmlResultElement.parents('.onlywindows').length == 1){
			htmlResultElement.parents('.onlywindows').parent().prev().find('.show-all').click();
		}
		htmlResultElement.addClass('foundThroughSearch');
		var stop = htmlResultElement.offset().top;
		$("html, body").animate({ scrollTop: stop - navbarsize - 130}, 200);
	}else if($this.data('json') == 'graph'){
		var originalPos = $this.data('index');
		htmlResultElement = $("#main *[data-pos=" + originalPos + "]").parent();
		if(searchResultsErrorHandling(htmlResultElement, $this) == 'error'){
			return
		}
		var elementHref = htmlResultElement.attr('xlink:href');
		var nodeId = elementHref.substring(1);
		var wrapperElement = htmlResultElement.closest('.graphWrapper');
		if(wrapperElement.hasClass('svgGraph')){
			var targetId = wrapperElement.data('targetid');
			graphId = 'graphWrapper_'+targetId;
		}else if(wrapperElement.hasClass('cfgGraph')){
			var targetId = wrapperElement.data('functionid');
			graphId = 'cfgWrapper_'+targetId;
		}else if(wrapperElement.hasClass('callGraph')){
			var targetId = wrapperElement.data('targetid');
			graphId = 'callgraphWrapper_'+targetId;
		}
		jumpToNode(graphId, nodeId, wrapperElement, targetId);
	}
	e.preventDefault();
});

window.jumpToNode = function(graphId, nodeId, wrapperElement, targetId){
	if(wrapperElement.hasClass('cfgGraph')){
		if(!$('#body_'+targetId).hasClass('in')){
			$('#body_'+targetId).prev().find('.accordion-toggle ').click();
			if(panZoomGraph[targetId] == undefined){
				initCfgGraph($('#body_'+targetId));
			}
		}
	}
	var svgGraphAdd = 0;
	if($('#' + graphId).hasClass('svgGraph')){  
		svgGraphAdd = 120;
	}
	var stop = $('#' + graphId).offset().top;

	$("html, body").animate({scrollTop: stop - navbarsize - 10 + svgGraphAdd}, 200);
	
	$('#'+graphId+' .highlightNode').attr('class', 'node');
    var polygon;
	if(wrapperElement.hasClass('svgGraph')){
		polygon = hideShowNodeEdges[targetId][nodeId].find('polygon');
		hideShowNodeEdges[targetId][nodeId].attr('class', 'node highlightNode');
	}else{
	  wrapperElement.find('.node title').each(function(){
	      if($(this).text() == nodeId){
	        $(this).parent().attr('class', 'node highlightNode');
	        polygon = $(this).parent().find('polygon');
	      }
	  });
	}
	var XYPoints = polygon.attr('points').split(' ');

	var xMin = 9999999999;
    var xMax = 0;
    var yMin = 9999999999;
    var yMax = 0;

	$.each(XYPoints, function( index, value ){
	    value = value.split(',');
	    if(value[0] < xMin){
	    	xMin = value[0];
	    }else if(value[0] > xMax){
	    	xMax = value[0];
	    };
	    value[1] = Math.abs(value[1]);
	    if(value[1] < yMin){
	    	yMin = value[1];
	    }else if(value[1] > yMax){
	    	yMax = value[1];
	    };
	});
	var xPosition = ((parseInt(xMax) - parseInt(xMin))/2) + parseInt(xMin);
	var yPosition = ((parseInt(yMax) - parseInt(yMin))/2) + parseInt(yMin);

	XYPoints = XYPoints[0].split(',');

	if(wrapperElement.hasClass('svgGraph')){
		var targetId = wrapperElement.data('targetid');
		graphId = targetId;
		panZoomGraph[graphId].zoom(maxZoom*0.5);
	}else if(wrapperElement.hasClass('cfgGraph')){
		var targetId = wrapperElement.data('functionid');
		graphId = targetId;
		panZoomGraph[graphId].zoom(maxZoom*0.05);
	}else if(wrapperElement.hasClass('callGraph')){
		var targetId = wrapperElement.data('targetid');
		graphId = targetId+'callgraph';
		panZoomGraph[graphId].zoom(maxZoom*0.09);
	}

	var realZoom= panZoomGraph[graphId].getSizes().realZoom;

	panZoomGraph[graphId].pan({
		x: -(xPosition*realZoom)+(panZoomGraph[graphId].getSizes().width/2),
		y: -((panZoomGraph[graphId].getSizes().viewBox.height-yPosition)*realZoom)+(panZoomGraph[graphId].getSizes().height/2)
	});
};

var expandAllParents = function(htmlResultElement){
	
	
	
	<!-- // ]/ -->

	// if signatures are hidden because of expert-mode, show them
	if(htmlResultElement.parents('.show-source')){
		if(htmlResultElement.is(':hidden')){
			$('#expertMode').click();
		}
	}

	// Render elements if they are not in the page
	if(htmlResultElement.parents('.accordion-wrapper').hasClass('collapsed')){
		htmlResultElement.parents('.accordion-wrapper').find('.accordion-toggle').click();
	}
	if(htmlResultElement.hasClass('collapsed')){
		htmlResultElement.find('.accordion-toggle').click();
	}
	if(htmlResultElement.parents('.accordion-body').prev().find('.accordion-wrapper').hasClass('collapsed')){
		htmlResultElement.parents('.accordion-body').prev().find('.accordion-toggle').click();
	}
	if(htmlResultElement.prev().find('.accordion-wrapper').hasClass('collapsed')){
		htmlResultElement.prev().find('.accordion-toggle').click();
	}
	// Open all parent accordions
	if(htmlResultElement.parents('.collapse').length > 0){
		if(!htmlResultElement.parents('.collapse').hasClass('in')){
			htmlResultElement.parents('.collapse').prev().find('.accordion-toggle').click();
		}
		expandAllParents(htmlResultElement.parents('.collapse'));
	}
};
search = function(searchTermPar){
	// Show search results if hidden
	if($('#searchResultsWrapper').css('display') == 'none'){
		getSearchResultsWrapperPos(250);
	}
	cleanUpSearchResults();
	searchTerm = searchTermPar;
	searchTermEscaped = searchTermPar;
	searchTermEscaped = searchTermEscaped.toLowerCase();
	searchTermEscaped = searchTermEscaped.replace(/\r?\n|\r|\t|[^\w\s\<\>\{\}\.]| /ig, '');
	// Search string must have more than 3 characters, else show appropriate error message
	if(searchTermEscaped.length > 3){
		$('#searchResultsError').hide();
		$('#searchInProgress').show();

		// setTimeout 0ms to wait for all other code to finish before executing the code below
		setTimeout(function(){
			if (typeof behavior == 'object') {
				currentJson = 'behavior';
				ObjectValues(behavior);
				endThisSearch = false;
			}
			if (typeof disasm == 'object') {
				currentJson = 'disasm';
				ObjectValues(disasm);
				endThisSearch = false;
			}
			if (typeof chrono == 'object') {
				currentJson = 'chrono';
				ObjectValues(chrono);
				endThisSearch = false;
			}
			currentJson = 'html';
			searchHtml(searchTerm);
			if($('#searchResults .searchResultItem').length == 0){
				$('#searchInProgress').hide();
				$('#searchResultsEmpty').show();
				$('#searchResultsEmpty #searchResultsEmptyValue').text(searchTerm);
				$('#searchTitleBarTextWrapper').hide();
			}else{
				$('#searchInProgress').hide();
				$('#searchTitleBarTextWrapper').show();
				$('#searchTerm').text(searchTerm);
			}
			$('#searchResults').scrollTop(0);
		}, 0);
	}else{
		$('#searchInProgress').hide();
		$('#searchResultsError').show();
	}
};
var cleanUpSearchResults = function(){
	$('#searchResultsBehavior').hide();
	$('#searchResultsChrono').hide();
	$('#searchResultsDisasm').hide();
	$('#searchResultsHtml').hide();
	$('#searchResultsGraph').hide();
	$('#searchResultsEmpty').hide();
	$('.searchResultItem').remove();
	chronoIndex = -1;
	disasmIndex = -1;
	searchResultIndex = 0;
	sectionIndex = 0;
};
// Show error if search result can't get found in html page.
var searchResultsErrorHandling = function($elementToOpen, $this){
	if($elementToOpen.length == 0){
		if($this.parent().parent().find('.not-accessible').length == 0){
			$this.parent().parent().append('<br><strong class="not-accessible">This search result is not accessible in the page</strong>');
			$this.parent().parent().replaceWith($('<li class="searchError searchResultItem">' + $this.parent().parent().html() + '</li>'));
		}
		return 'error';
	}
};
