var $titleElement;
var findTitle = function($element){
  if($element.find('*[data-pos]').length > 0){
  	tagName = $element.find('*[data-pos]').get(0).tagName;
  	if(tagName[0] != 'H'){
  	  findTitle($element.prev());
  	}else{
  	  $titleElement = $element;
  	}
  }else{
  	$titleElement = $element.closest('H2');
  }
}
var searchHtml = function(searchTermHtml) {
    foundGraphElement = false;
    foundHtmlElement = false;
    searchTermHtml = searchTermHtml.replace(/\r?\n|\r|\t|[^\w\s\<\>\{\}\.]| /ig, '');

    foundElementArr = [];
    foundGraphElementArr = [];

    for (n = 0; n < window['searchableElements'].length; n++) {
        var text = window['searchableElements'][n].innerText;
        if (text != undefined) {
            textLowercase = text.toLowerCase();
            textLowercase = textLowercase.replace(/\r?\n|\r|\t|[^\w\s\<\>\{\}\.]| /ig, '');
            searchTermHtml = searchTermHtml.toLowerCase();
            if (textLowercase.indexOf(searchTermHtml) >= 0) {
                foundElementArr.push(window['searchableElements'][n]);
            }
        }
    }

    $(window['searchableElementsGraph']).each(function(){
    	var text = $(this).text();
    	if (text != undefined) {
    		textLowercase = text.toLowerCase();
    		textLowercase = textLowercase.replace(/\r?\n|\r|\t|[^\w\s\<\>\{\}\.]| /ig, '');
    		searchTermHtml = searchTermHtml.toLowerCase();
    		if (textLowercase.indexOf(searchTermHtml) >= 0) {
    		    foundGraphElementArr.push($(this));
    		}
    	}
    });

    for (i = 0; i < foundElementArr.length; i++) {
        var foundElement = $(foundElementArr[i]);
        if (foundElement.data('pos') != undefined && !foundElement.hasClass('btn')) {
            if (sectionIndex < maxResultsPerSection) {
                var currentJson = 'html';
                var dataPos = foundElement.data('pos');

                try {
                    if (foundElement.get(0).tagName[0] == 'H') {
                        $titleElement = foundElement;
                        var context = getContext($titleElement.data('pos') + 1);
                    } else {
                        if (foundElement.closest('.accordion-body').prev().length > 0) {
                            findTitle(foundElement.closest('.accordion-body').prev());
                        } else {
                            if (foundElement.closest('.table.table-bordered').prev().length > 0) {
                                findTitle(foundElement.closest('.table.table-bordered').prev());
                            }
                        }
                        var context = getContext($titleElement.find('*[data-pos]').data('pos') + 1);
                    }
                } catch (err) {
                    context = '';
                    console.log('No Context Found - ' + err);
                }
                $('#searchResultsHtml').append(generateSearchResultItem(foundElement.text(), dataPos, context, currentJson));
                foundHtmlElement = true;
            }
        }
        if (foundHtmlElement) {
            $('#searchResultsHtml').show();
        }
        sectionIndex++;
        searchResultIndex++;
    }
    for (i = 0; i < foundGraphElementArr.length; i++) {
    	var foundElement = foundGraphElementArr[i];
    	var dataPos = foundElement.data('pos');
    	var currentJson = 'graph';
    	betterContext = $('#'+foundElement.data('id'));
    	var graphId = betterContext.data('targetid');
    	if(graphId == undefined){
    		graphId = betterContext.data('functionid');
    	}
    	var context = 'Graph';
    	if(betterContext.hasClass('svgGraph')){
    	  context = 'Execution Graph ID: ' + graphId;
    	}else if(betterContext.hasClass('callGraph')){
    		context = 'Call Graph ID: ' + graphId;
    	}else if(betterContext.hasClass('cfgGraph')){
    		context = 'Control Flow Graph Function ID: ' + graphId;
    	}
    	if(dataPos != undefined && foundElement != []){
    		$('#searchResultsGraph').append(generateSearchResultItem(foundElement.text(), dataPos, context, currentJson));
    		foundGraphElement = true;
    	}
    }
    if (foundGraphElement) {
        $('#searchResultsGraph').show();
    }
};

var generateSearchResultItem = function(searchTerm, index, context, currentJson, k){
		var searchTermShort = '';
		if(escapeHtml(searchTerm).length > 60){
			searchTermShort = escapeHtml(searchTerm).substring(0,60) + '...';
		}else{
			searchTermShort = escapeHtml(searchTerm);
		}
		var $searchResultItem = $("<li class='searchResultItem'>"
		+ "<strong><a data-json='"
		+ escapeHtml(currentJson) + "' "
		+ (typeof k !== "undefined" ? "data-key='" + k + "'" : "")
		+ " class='searchJump' title='"+escapeHtmlWithoutWbr(searchTerm).substring(0,300)+"' href='#' data-index='" + index + "'>"
		+ searchTermShort
		+ "</a></strong><br>"
		+ escapeHtml(context)
		+ "</li>");
		return $searchResultItem;
};
