// Make :contains case insensitive and escape special characters, overwirte old selector for current JQuery Version (1.7.2)
$.expr[':'].contains = function(a, i, m) {
	return jQuery(a).text().toLowerCase().replace(/\r?\n|\r|\t|[^\w\s\<\>\{\}\.]| /ig, '').indexOf(m[3].toLowerCase().replace(/\r?\n|\r|\t|[^\w\s\<\>\{\}\.]| /ig, '')) >= 0;
};





