var createPieSignature = function(data, elementId, act, legend){
  svg = d3.select("#"+elementId+"-svg");
  canvas = d3.select("#"+elementId+"-canvas");


  pie = d3.layout.pie();
  pie.value(function (d, i) {
    return d.values;
  });
  cDim = {
    height: 370,
    width: 500,
    innerRadius: 80,
    outerRadius: 140,
    labelRadius: 175
  }
  svg.attr({
    height: cDim.height,
    width: cDim.width
  });
  canvas.attr("transform", "translate(" + (cDim.width / 2) + "," + (cDim.width / 2) + ")");
  pied_colors = d3.scale.category10();
  
  squareWidth = $('#pie-chart-wrapper-signature').width();
  radius = squareWidth * 0.35;
  arc = d3.svg.arc()
    .innerRadius(radius - (radius*0.55))
    .outerRadius(radius - (radius*0.2));

  piedata = pie(data);
  art = d3.select("#"+elementId);
  art.selectAll(".pie-segment").remove();
  enteringArcs = art.selectAll(".pie-segment").data(piedata).enter();
  enteringArcs.append("path")
    .attr("class", "pie-segment")
    .attr("d", arc)
    .attr("transform", "translate(-5,-35)")
    .attr('values', function(d) { return d.data.values; })
    .attr('name', function(d) { return d.data.name; })
    .attr('color', function(d, i) { return pied_colors(i); })
    .style("fill", function (d, i) { return pied_colors(i); });
  if(legend == true){
    html = '<ul class="legendPie" style="list-style: none; margin-left: 3%; margin-bottom: 4%; margin-top: 1%;">';
    element = '#pie-chart-signature';
    $(element+' .pie-segment').each(function(i){
      html += '<li class="link" style="white-space: nowrap;"><span style="color:'+$(this).attr('color')+'; font-weight: bold;font-size: 32px; vertical-align: -7px;">•</span><span class="linktext"> '+$(this).attr('name')+'</span></li>';
    });
    html += '</ul>';
    $(element).append(html);
    setTimeout(function(){
      var legendHeight = $('#pie-chart-signature .legendPie').height();
      var pieChartWrapperHeight = $('#pie-chart-wrapper-signature').height();
    }, 10);
  }
};


