var createPieSignaturePreview = function(data, elementId, act){
  svg = d3.select("#"+elementId+"-svg");
  canvas = d3.select("#"+elementId+"-canvas");

  pie = d3.layout.pie();
  pie.value(function (d, i) {
    return d.values;
  });
  squareWidth = $('.overviewBlock').width();
  radius = squareWidth * 0.52;
  cDim = {
    height: squareWidth,
    width: squareWidth
  }
  svg.attr({
    height: cDim.height,
    width: cDim.width
  });
  canvas.attr("transform", "translate(" + (cDim.width / 2) + "," + (cDim.width / 2) + ")");
  pied_colors = d3.scale.category10();
  
  arc = d3.svg.arc()
    .innerRadius(radius - (radius*0.55))
    .outerRadius(radius - (radius*0.2));
  arcOver = d3.svg.arc()
    .innerRadius(radius - (radius*0.6))
    .outerRadius(radius - (radius*0.15));

  piedata = pie(data);
  var art = d3.select("#"+elementId);
  art.selectAll(".pie-segment-preview").remove();
  var enteringArcs = art.selectAll(".pie-segment-preview").data(piedata).enter();
  enteringArcs.append("path")
    .on("mouseover", function(d) {
        d3.select(this).transition()
          .duration(1000)
          .attr("d", arcOver);
        })
    .on("mouseout", function(d) {
        d3.select(this).transition()
          .duration(1000)
          .attr("d", arc);
        })
    .attr("class", "pie-segment-preview")
    .attr("d", arc)
    .attr('values', function(d) { return d.data.values; })
    .attr('name', function(d) { return d.data.name; })
    .attr('color', function(d, i) { return pied_colors(i); })
    .style('fill', function (d, i) { return pied_colors(i); });
};

