$(document).on('click', '.jumpToActivity', function(e){
	e.preventDefault();
	$('.jumpToActivityFound').removeClass('jumpToActivityFound');
	var activityToJumpTo = $(this).attr('href');
	var activityToJumpTo = activityToJumpTo.split("||");
	var categoryUpper = activityToJumpTo[1].charAt(0).toUpperCase() + activityToJumpTo[1].slice(1);
	var jumpToElement = $(activityToJumpTo[0]).next().next().find('h4:contains("'+categoryUpper+' Activities")');
	jumpToElement.parent().addClass("jumpToActivityFound");
	$('html, body').animate({
		scrollTop: jumpToElement.offset().top - 80
	}, 2000);
});
$(document).on('click', '#pie-chart .wedge', function(e){
	var link = $(this).attr('pid') + $(this).attr('md5');
	if($('.legendPie a[href*="'+link+'"]').length > 0){
		$('.legendPie a[href*="'+link+'"]').click();
	}
});
var createLegendPie = function(element, link){
	$('#pie-chart .legendPie').remove();
	html = '<ul class="legendPie" style="list-style: none; margin-left: 3%; margin-bottom: 4%;">';
	$(element+' .wedge').each(function(i){
		var link = '';
		if($(this).attr('pid')||$(this).attr('md5')){
			link = '<a class="jumpToActivity" href="#'+$(this).attr('pid')+$(this).attr('md5')+'||'+$(this).attr('act')+'">'+$(this).attr('name')+'</a>';
		}else{
			link = $(this).attr('name').charAt(0).toUpperCase() + $(this).attr('name').slice(1);
		}
		item = {};
		item.color = $(this).attr('color');
		item.link = link;
		html += '<li style="width:230px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;"><span style="color:'+item.color+'; font-weight: bold;font-size: 32px; vertical-align: -7px;">•</span> '+item.link+'</li>';
	});
	html += '</ul>';
	$(element).append(html);
	setTimeout(function(){
		var legendHeight = $('#pie-chart .legendPie').height();
		var pieChartWrapperHeight = $('#pie-chart-wrapper').height();
		$('#pie-chart .legendPie').css('margin-top',(pieChartWrapperHeight/2)-(legendHeight/2)+'px');
	}, 10);
}

var removeEmptyData = function(data){
	var dataLength = data.length;
	var data2 = [];
	for (var i = 0; i < dataLength; i++) {
	    if(data[i].values != 0){
	    	data2.push(data[i]);
	    }
	}
	return data2;
};
var radius, arc, arcOver;
var setupPie = function(){
	svg = d3.select("#pie-chart-svg");
	canvas = d3.select("#pie-chart-canvas");
	pie = d3.layout.pie()
	pie.value(function (d, i) {
		return d.values;
	});
	radius = 160;

	cDim = {
		height: 370,
		width: 500,
		innerRadius: radius - 80,
		outerRadius: radius - 20,
		labelRadius: 175
	}
	svg.attr({
		height: cDim.height,
		width: cDim.width
	});
	canvas.attr("transform", "translate(" + (cDim.width / 2) + "," + (cDim.width / 2) + ")");
	pied_colors = d3.scale.category10();
	
	arc = d3.svg.arc()
		.innerRadius(radius - 80)
		.outerRadius(radius - 20);
	arcOver = d3.svg.arc()
		.innerRadius(radius - 90)
		.outerRadius(radius - 10);
};
var createPie = function(data, elementId, act){
	piedata = pie(removeEmptyData(data));
	art = d3.select("#"+elementId);
	art.selectAll(".wedge").remove();
	enteringArcs = art.selectAll(".wedge").data(piedata).enter();

	enteringArcs.append("path")
		.on("mouseover", function(d) {
				d3.select(this).transition()
					.duration(1000)
					.attr("d", d3.svg.arc()
						.innerRadius(160 - 90)
						.outerRadius(160 - 10));
				})
		.on("mouseout", function(d) {

				d3.select(this).transition()
					.duration(1000)
					.attr("d", d3.svg.arc()
						.innerRadius(160 - 80)
						.outerRadius(160 - 20));
				})
		.attr("class", "wedge")
		.attr("d", d3.svg.arc()
			.innerRadius(160 - 80)
			.outerRadius(160 - 20))
		.attr("transform", "translate(-5,-35)")
		.attr('pid', function(d) { return d.data.pid; })
		.attr('md5', function(d) { return d.data.md5; })
		.attr('color', function(d, i) { return pied_colors(i); })
		.attr('act', act)
		.attr('name', function(d) { return d.data.name; })
		.style("fill", function (d, i) { return pied_colors(i); });
};

