	var createChart = function(element, what){
		// Define Margins
		var divWidth = parseInt($('#main').width()*0.65);
		var divHeight = divWidth * 0.53;
		var margin = {top: 20, right: 30, bottom: 30, left: 50},
			width = divWidth - margin.left - margin.right,
			height = divHeight - margin.top - margin.bottom;
		var x = d3.scale.linear().range([0, width*0.6]);
		var y = d3.scale.linear().range([height*0.6, 0]);
		var color = d3.scale.category10();
		// Create X and Y Axis
		var xAxis = d3.svg.axis()
			.tickFormat(function(d) { return d * 0.001; }) // Miliseconds to seconds
			.scale(x)
			.ticks(4)
			.orient("bottom");
		var yAxis = d3.svg.axis()
			.tickFormat(function(d) { if(what == 'memoryusage'){if((d * 0.000001) < 1){return (d * 0.000001).toFixed(2)}else{return (d * 0.000001)};}else{return d;} })
			.ticks(4)
			.scale(y)
			.outerTickSize(10)
			.orient("left");
		var line = d3.svg.line()
			.interpolate("basis")
			.x(function(d) { return x(d.timestamp); })
			.y(function(d) { return y(d[what]); });
		var svg = d3.select(element).append("svg")
			.attr("width", width + margin.left + margin.right-(divWidth*0.1))
			.attr("height", (height + margin.top + margin.bottom)*0.65)
			.append("g")
			.attr("transform", "translate(" + margin.left + "," + margin.top + ")");
		// Apply a color for every process
		color.domain(d3.keys(processes).filter(function(key) { return key; }));
		// set min and max value for x and y Axis
		var maxTimestamp = d3.max(processes, function(c) { return d3.max(c.points, function(v) { return parseInt(v['timestamp']); }); })
		x.domain([
			0, maxTimestamp
		]);
		if(what == 'memoryusage'){
			yMax = d3.max(processes, function(c) { return d3.max(c.points, function(v) { return parseInt(v[what]); }); })
		}else if(what == 'cpuusage'){ 
			yMax = 100
		};
		y.domain([
			0,yMax
		]);
		// Draw line and label for axis
		svg.append("g")
			.attr("class", "x-axis")
			.attr("transform", "translate(0,"+ height*0.6 +")")
			.call(xAxis)
			.append("text")
			.attr("x", width*0.6)
			.attr("y", "30")
			.style("text-anchor", "end")
			.text("s");

		var yAxisText = '';
		if(what == 'memoryusage'){yAxisText = 'MB';}
		svg.append("g")
			.attr("class", "y-axis")
			.call(yAxis)
			.append("text")
			.attr("y", 6)
			.attr("dy", "1")
			.attr("x", -30)
			.style("text-anchor", "end")
			.text(yAxisText);

		// Convert Strings to Ints and set timestamp
		var lastTotalMemory = {};
		lastTotalMemory.link = '';
		lastTotalMemory.value = 0;
		var lastTotalCpu = {};
		lastTotalCpu.link = '';
		lastTotalCpu.value = 0;

		var longestProcessFillUp = 0;
		processes.forEach(function(d){
			if(longestProcessFillUp < d.points.length){
				longestProcessFillUp = d.points.length;
			}
		});
		processes.forEach(function(d){
			p = 0;
			totalMemory = 0;
			totalCpu = 0;

			d.points = d.points.filter(function(point) {
				return point.timestamp >= 0;
			});

			d.points.forEach(function(d, i){

				d.timestamp = +d.timestamp;
				d.memoryusage = +d.memoryusage;
				d.cpuusage = +d.cpuusage;
				totalMemory += +d.memoryusage;
				totalCpu += +d.cpuusage;
				p++;
			});
			// If a process dies, fill up values with 0
			if(longestProcessFillUp > p){
				d.points.push({"timestamp":maxTimestamp, "memoryusage":0,"cpuusage":0});
			}
			if(lastTotalCpu.value < totalCpu){
				lastTotalCpu.value = totalCpu;
				lastTotalCpu.link = d.pid + d.md5;
			}
			if(lastTotalMemory.value < totalMemory){
				lastTotalMemory.value = totalMemory;
				lastTotalMemory.link = d.pid + d.md5;
			}
		});
		// Create Process Group
		var process = svg.selectAll(".process")
			.data(processes)
			.enter().append("g")
			.attr("class", "process");
		var colorsPerProcess = {};
		process.append("path")
			.attr("class", "flowchart-line")
			.attr("d", function(d) { return line(d.points); })
			.on("mouseover", function(d) {
				d3.select(this).transition()
					.duration(1000)
					.style("stroke-width", 6);
				})
			.on("mouseout", function(d) {
				d3.select(this).transition()
					.duration(1000)
					.style("stroke-width", function(d){ var currentLink = d.pid + d.md5; if(currentLink == lastTotalCpu.link){return 3;}else{return 2;} });
				})
			.attr("data-legend",function(d) { return d.process;})
			.attr("data-link",function(d) { return d.pid + d.md5;})
			.attr("data-color",function(d) { 
				var currentLink = d.pid + d.md5;
				if(what == 'cpuusage'){
					if(currentLink == lastTotalCpu.link){
						colorsPerProcess[currentLink] = '#ff0000';
						return '#ff0000';
					}else{
						colorsPerProcess[currentLink] = color(d.pid + d.md5);
						return color(d.pid + d.md5);}
				}else if(what == 'memoryusage'){
					if(currentLink == lastTotalMemory.link){
						colorsPerProcess[currentLink] = '#ff0000';
						return '#ff0000';
					}else{
						colorsPerProcess[currentLink] = color(d.pid + d.md5);
						return color(d.pid + d.md5);
					}
				} 
			})
			.style("stroke-width", function(d){ var currentLink = d.pid + d.md5; if(currentLink == lastTotalCpu.link){return 3;}else{return 2;} })
			.style("stroke", function(d) { 
				var currentLink = d.pid + d.md5;
				if(what == 'cpuusage'){
					if(currentLink == lastTotalCpu.link){
						return '#ff0000';
					}else{
						return colorsPerProcess[d.pid + d.md5];}
					}else if(what == 'memoryusage'){
						if(currentLink == lastTotalMemory.link){
							return '#ff0000';
						}else{
							return colorsPerProcess[d.pid + d.md5];
						}
					}
				});
		createLegendFlowchart(element);
		// Create Pie

		var diameter = width*0.25;
		var arc2 = d3.svg.arc()
			.innerRadius((parseInt(diameter)/2)-35)
			.outerRadius(parseInt(diameter)/2);
		var arc2Over = d3.svg.arc()
			.innerRadius((diameter/2)-42)
			.outerRadius((diameter/2)+7);
		pie2 = d3.layout.pie();
		var isPieEmpty = true;
		pie2.value(function (d, i) {
			if(what == 'cpuusage'){
				if(d.totalCpu > 0){
					isPieEmpty = false;
				}
				return d.totalCpu;
			}else if(what == 'memoryusage'){
				if(d.totalMemory > 0){
					isPieEmpty = false;
				}
				return d.totalMemory;
			}
		});
		piedata = {};
		piedata = pie2(totalUsage);
		enteringArcs = svg.selectAll(".simplePieChart"+what).data(piedata).enter();
		if(!isPieEmpty){
			enteringArcs.append("path")
				.attr("class", "simplePieChart")
				.attr("data-empty",function(d) { return d.data.pid + d.data.md5;})
				.attr("d", d3.svg.arc()
						.innerRadius(120 - 60)
						.outerRadius(120 - 20))
				.attr("data-empty2",function(d) { return d.data.pid + d.data.md5;})
				.attr("transform", "translate("+(width*0.6+(diameter/2)+20)+","+((divHeight/2)-(diameter/2))+")")
				.attr("data-link",function(d) { return d.data.pid + d.data.md5;})
				.on("mouseover", function(d) {
					d3.select(this).transition()
						.duration(1000)
						.attr("d", d3.svg.arc()
						.innerRadius(120 - 65)
						.outerRadius(120 - 15));
					})
				.on("mouseout", function(d) {
					d3.select(this).transition()
						.duration(1000)
						.attr("d", d3.svg.arc()
						.innerRadius(120 - 60)
						.outerRadius(120 - 20));
					})
				.style("fill", function (d, i) {
					return colorsPerProcess[d.data.pid + d.data.md5];
				});
		}
	};

	createChart('#cpuusage', 'cpuusage');
	createChart('#memoryusage', 'memoryusage');




function checkUrl(url){
  if (window.location.protocol === "file:" && url.includes('linux/web/reports')) {
    console.log('Local: Download Files True!');
    return true;
  }

  if(url != undefined){
    var showUrl1 = false;
    var showUrl2 = false;
    var showUrl3 = false;
    urlSlash = url.split('//');
    if(urlSlash[0] == 'http:' || urlSlash[0] == 'https:'){
      showUrl1 = true;
    }
    urlRest = url.split('/');
    for (i = 0; i < urlRest.length; i++) {
      if(urlRest[i] == 'analysis'){
        showUrl2 = true;
      }
      if(urlRest[i].split('#')[0] == 'html'){
        showUrl3 = true;
      }
    };
    if(showUrl1 && showUrl2 && showUrl3){
      return true;
    }else{
      return false;
    };
  }else{
    return false;
  };
};

