function reduceNodes(node) {

  if (typeof node.name !== 'undefined') {
    if(node.name == 'Executed Functions' || node.name == 'Non-executed Functions'){
      delete node.children;
    }
  }

  if (typeof node.parentName !== 'undefined' && typeof node.currentObjectParent !== 'undefined' && typeof node.currentObjectParent.children !== 'undefined') {
    if(node.parentName == 'System Behavior' && node.currentObjectParent.children.length > 4){
      delete node.children;
    }
  }


  if (typeof node.children !== 'undefined') {
    if(!node.children) {
        return;
    }
  }

  if (typeof node.children !== 'undefined') {
    node.children.forEach(function(d) {
        reduceNodes(d);
    })
  }
}

function consoleHirarchy(node) {
  var name = node.name.replace(/\n|\r/g, "");
  name = name.trim();
  name = name.replace('\t','');
  var tabs = '';
  var hierarchy = node.hierarch -1;
  for (var i = 0; i < node.hierarchy; i++) {
    tabs += '&nbsp;&nbsp;&nbsp;';
  }

  $('#consoleHirarchy').append(tabs+'h'+node.hierarchy + ': ' + name + '<br />');

  if (typeof node.children !== 'undefined') {
    node.children.forEach(function(d) {
        consoleHirarchy(d);
    })
  }
}

