function findIpOrUrl(regexString) {
var regex = /(?:(?:https?|ftp|file):\/\/|www\.|ftp\.|winmgmts:\\\\)(?:\([-A-Z0-9+&@#\/\\%=~_|$?!:,.]*\)|[-A-Z0-9+&@#\/\\%=~_|$?!:,.])*(?:\([-A-Z0-9+&@#\/\\%=~_|$?!:,.]*\)|[A-Z0-9+&@#\/\\%=~_|$])/igm;
    var regexArray = regexString.split(regex);
    var newString = '';
    tagOpened = false;

    for (var n = 0; n < regexArray.length; n++) {
        if(n > 1){
            var indexOf = regexString.indexOf(regexArray[n-1]);
            regexString = regexString.slice(0, indexOf + regexArray[n-1].length) + '<strong style="color: #0044cc;">' + regexString.slice(indexOf + regexArray[n-1].length);
            indexOf = regexString.indexOf(regexArray[n]);
            regexString = regexString.slice(0, indexOf) + '</strong>' + regexString.slice(indexOf);
        }else{
            var indexOf = regexString.indexOf(regexArray[n]);
            if(!tagOpened){
                tagOpened = true;
                regexString = regexString.slice(0, indexOf + regexArray[n].length) + '<strong style="color: #0044cc;">' + regexString.slice(indexOf + regexArray[n].length);
            }else{
                tagOpened = false;
                regexString = regexString.slice(0, indexOf) + '</strong>' + regexString.slice(indexOf);
            }
        }
    };
    return regexString;
}

function cleanUpJs(arr, deleteValue) {
    for (var i = 0; i < arr.length; i++) {
        if (arr[i] == deleteValue) {
            arr.splice(i, 1);
            i--;
        }
    }
    return arr;
}

function jsSyntax(string, escape) {
    var string = string;
    if (string[0] != "'") {
        words = string.split(/[ ,().'"\n|!@/\\\#%^&-+:=;*]+/);
        differentChars = string.split(/[^ ,().'"\n|!@/\\\#%^&-+:=;*]+/);
        words = cleanUpJs(words, '');
        differentChars = cleanUpJs(differentChars, '');
        diffCharsRun = 0;
        wordsRun = 0;
        var newHtml = '';
        diffCharsIndex = string.indexOf(differentChars[0]);
        wordsIndex = string.indexOf(words[0]);
        varCharIsFirst = 0;
        if (words.length + differentChars.length > 1) {
            if (diffCharsIndex > wordsIndex) {
                varCharIsFirst = 1;
            } else {
                varCharIsFirst = 0;
            }
        } else {
            if (words.length == 1) {
                varCharIsFirst = 1;
            } else {
                varCharIsFirst = 0;
            }
        }
        var isString = false;
        var openingQuotationMarkSeen = false;
        var openingQuotationMarkType = '';
        var alreadyAdded = false;
        var skipNext = false;

        for (var i = 0; i < (words.length + differentChars.length); i++) {
            highlightedWord = '';
            if (((i % 2) == varCharIsFirst)) {
                for (var k = 0; k < differentChars[diffCharsRun].length; k++) {
                    if (!skipNext) {
                        if (differentChars[diffCharsRun][k].indexOf('"') !== -1 && openingQuotationMarkType != "'") {
                            if (!openingQuotationMarkSeen) {
                                isString = true;
                                openingQuotationMarkSeen = true;
                                openingQuotationMarkType = '"';
                                alreadyAdded = true;
                                newHtml += differentChars[diffCharsRun][k] + '<strong style="color: #9e7f4d">';
                            } else if (openingQuotationMarkType == '"') {
                                isString = false;
                                openingQuotationMarkSeen = false;
                                openingQuotationMarkType = '';
                                newHtml += '</strong>' + differentChars[diffCharsRun][k];
                            }
                        } else if (differentChars[diffCharsRun][k].indexOf("'") !== -1 && openingQuotationMarkType != '"') {
                            if (!openingQuotationMarkSeen) {
                                isString = true;
                                openingQuotationMarkSeen = true;
                                openingQuotationMarkType = "'";
                                alreadyAdded = true;
                                newHtml += differentChars[diffCharsRun][k] + '<strong style="color: #9e7f4d">';
                            } else if (openingQuotationMarkType == "'") {
                                isString = false;
                                openingQuotationMarkSeen = false;
                                openingQuotationMarkType = '';
                                newHtml += '</strong>' + differentChars[diffCharsRun][k];
                            }
                        } else {
                            newHtml += differentChars[diffCharsRun][k];
                        }
                    } else {
                        newHtml += differentChars[diffCharsRun][k];
                        skipNext = false;
                    }
                    if (differentChars[diffCharsRun][k] == '\\' && differentChars[diffCharsRun][k - 1] != '\\' && differentChars[diffCharsRun][k + 1] == openingQuotationMarkType && escape) {
                        skipNext = true;
                    }
                }

                if (isString && words[wordsRun] != undefined) {
                    newHtml += words[wordsRun];
                    wordsRun++;
                }
                diffCharsRun++;
            } else if (!isString) {
                var lowercaseword = words[wordsRun].toLowerCase();
                if (lowercaseword == 'public') {
                    // Qualifiers:
                    highlightedWord = '<strong style="color: #284aa0">' + words[wordsRun] + '</strong>';
                } else if (lowercaseword == 'function') {
                    // Methods:
                    highlightedWord = '<strong style="color: #284aa0">' + words[wordsRun] + '</strong>';
                } else if (lowercaseword == 'var' || lowercaseword == 'typeof') {
                    // Type:
                    highlightedWord = '<strong style="color: #008a25">' + words[wordsRun] + '</strong>';
                } else if (lowercaseword == 'switch' || lowercaseword == 'case' || lowercaseword == 'continue' || lowercaseword == 'break' || lowercaseword == 'catch' || lowercaseword == 'try' || lowercaseword == 'if' || lowercaseword == 'else' || lowercaseword == 'for' || lowercaseword == 'then' || lowercaseword == 'each' || lowercaseword == 'in' || lowercaseword == 'while' || lowercaseword == 'to' || lowercaseword == 'step') {
                    // Conditions:
                    highlightedWord = '<strong style="color: #551390">' + words[wordsRun] + '</strong>';
                } else if (lowercaseword == 'return') {
                    // return
                    highlightedWord = '<strong style="color: #660083">' + words[wordsRun] + '</strong>';
                } else if (lowercaseword == 'GoSub') {
                    highlightedWord = '<strong style="color: #00ae46">' + words[wordsRun] + '</strong>';
                } else if (lowercaseword == 'array' || lowercaseword == 'enumerator' || lowercaseword == 'error' || lowercaseword == 'float32array' || lowercaseword == 'float64array' || lowercaseword == 'int8array' || lowercaseword == 'int16array' || lowercaseword == 'int32array' || lowercaseword == 'collator' || lowercaseword == 'datetimeformat' || lowercaseword == 'numberformat' || lowercaseword == 'json' || lowercaseword == 'map' || lowercaseword == 'math' || lowercaseword == 'number' || lowercaseword == 'object' || lowercaseword == 'regexp' || lowercaseword == 'set' || lowercaseword == 'string' || lowercaseword == 'symbol' || lowercaseword == 'vbarray' || lowercaseword == 'arraybuffer' || lowercaseword == 'arguments' || lowercaseword == 'boolean' || lowercaseword == 'dataview' || lowercaseword == 'date' || lowercaseword == 'debug' || lowercaseword == 'eval' || lowercaseword == 'activexobject' || lowercaseword == 'wscript') {
                    // Special Objects:
                    highlightedWord = '<strong style="color: #656565">' + words[wordsRun] + '</strong>';
                } else if (lowercaseword == 'true') {
                    // Boolean:
                    highlightedWord = '<strong style="color: #00a408">' + words[wordsRun] + '</strong>';
                } else if (lowercaseword == 'run' || lowercaseword == 'position' || lowercaseword == 'charset' || lowercaseword == 'fromcharcode' || lowercaseword == 'type' || lowercaseword == 'sleep' || lowercaseword == 'writetext' || lowercaseword == 'copyto' || lowercaseword == 'loadfromfile' || lowercaseword == 'loadfromfile' || lowercaseword == 'base64decode' || lowercaseword == 'localecompare' || lowercaseword == 'lastindexof' || lowercaseword == 'indexof' || lowercaseword == 'tolocalelowercase' || lowercaseword == 'tolocaleuppercase' || lowercaseword == 'concat' || lowercaseword == 'match' || lowercaseword == 'substring' || lowercaseword == 'search' || lowercaseword == 'tolocaleuppercase' || lowercaseword == 'localecompare' || lowercaseword == 'touppercase' || lowercaseword == 'substr' || lowercaseword == 'localecompare' || lowercaseword == 'parseint' || lowercaseword == 'unshift' || lowercaseword == 'trimright' || lowercaseword == 'trimleft' || lowercaseword == 'trim' || lowercaseword == 'toutcstring' || lowercaseword == 'totimestring' || lowercaseword == 'tostring' || lowercaseword == 'tosource' || lowercaseword == 'toprecision' || lowercaseword == 'tolocalestring' || lowercaseword == 'tolocaleformat' || lowercaseword == 'tolocaledatestring' || lowercaseword == 'tojson' || lowercaseword == 'toisostring' || lowercaseword == 'togmtstring' || lowercaseword == 'tofixed' || lowercaseword == 'toexponential' || lowercaseword == 'todatestring' || lowercaseword == 'throw' || lowercaseword == 'then' || lowercaseword == 'test' || lowercaseword == 'stringify' || lowercaseword == 'sub' || lowercaseword == 'strike' || lowercaseword == 'store' || lowercaseword == 'startswith' || lowercaseword == 'sqrt' || lowercaseword == 'split' || lowercaseword == 'splice' || lowercaseword == 'sort' || lowercaseword == 'reverse' || lowercaseword == 'normalize' || lowercaseword == 'map' || lowercaseword == 'length' || lowercaseword == 'folderexists' || lowercaseword == 'createfolder' || lowercaseword == 'namespace' || lowercaseword == 'getfolder' || lowercaseword == 'fileexists' || lowercaseword == 'copyhere' || lowercaseword == 'open' || lowercaseword == 'setrequestheader' || lowercaseword == 'setoption' || lowercaseword == 'settimeouts' || lowercaseword == 'send' || lowercaseword == 'status' || lowercaseword == '' || lowercaseword == 'deletefile' || lowercaseword == 'expandenvironmentstrings' || lowercaseword == 'charat' || lowercaseword == 'floor' || lowercaseword == 'join' || lowercaseword == 'gettime' || lowercaseword == 'gettimezoneoffset' || lowercaseword == 'random'|| lowercaseword == 'write' || lowercaseword == 'savetofile' || lowercaseword == 'close' || lowercaseword == 'read' || lowercaseword == 'getyear' || lowercaseword == 'ceil'  || lowercaseword == 'createobject'  || lowercaseword == 'getfile' || lowercaseword == 'getdate' || lowercaseword == 'getmonth' || lowercaseword == 'gethours' || lowercaseword == 'getminutes' || lowercaseword == 'getseconds' || lowercaseword == 'decodeuricomponent' || lowercaseword == 'atob'  || lowercaseword == 'btoa' || lowercaseword == 'copyfile' || lowercaseword == 'quit' || lowercaseword == 'writetofile' || lowercaseword == 'opentextfile' || lowercaseword == 'readfromfile' || lowercaseword == 'readline' || lowercaseword == 'checkfile' || lowercaseword == 'charcodeat' || lowercaseword == 'valueof') {
                    // Javascript Methods:
                    highlightedWord = '<strong style="color: #1074c9">' + words[wordsRun] + '</strong>';
                } else if (lowercaseword == 'false' || lowercaseword == 'undefined' || lowercaseword == 'null' || lowercaseword == 'nan') {
                    // Boolean:
                    highlightedWord = '<strong style="color: #bf0000">' + words[wordsRun] + '</strong>';
                } else {
                    highlightedWord = words[wordsRun];
                }
                newHtml += highlightedWord;
                wordsRun++;
            }
        }
        return newHtml;
    }
};

