function hideDynJs($element){
    if($element.html() != ''){
        var rightSideHeight = $element.height();
        $element.hide();
        var leftSideHeight = $element.parent().parent().find('.js-code.executedLine').height();
        if(rightSideHeight > leftSideHeight){
            $element.height(leftSideHeight + 18);
            if(leftSideHeight + 18 != rightSideHeight){
                if($element.find('.hideDynJs').length == 0){
                    $element.append('<li class="showDynJs">Show all Function Runs</li>');
                }else{
                    $element.find('.hideDynJs').html('Show all Function Runs');
                    $element.find('.hideDynJs').attr('class', 'showDynJs');
                }
            }
        }
        $element.show();
    }
}

