	  // Global Variables for Interface Logic
    var selection;
	  var selectedElement;
	  var selectedElementOffset;
	  var selectedElementWidth;
	  var selectedElementHeight;
	  // Functions for interface Logic
	 var clickReportTourElement = function(){
      if(typeof selectedElement == 'undefined'){
        return false;
      }
      reportTourElementSelecting = false;
      $(document).off('mousemove', appendReportTourHoverElement);
      $(document).off('click', clickReportTourElement);
      $('#selectElement').removeClass('active');
      $('#selectedElement').addClass('selected');
      $('#selectedElement').removeClass('empty');
      $('#selectedElement').html('Element selected');

      $('#selectedElement').attr('title', selectedElement.text());
      $('#reportTourExplanationBox').show();
      updateTitleAndDescription($('#reportTourTitle').val(), $('#reportTourDescription').val());
      $('#reportTourEntryList .active').data('selectedElement', selectedElement);
      var headerArr = [];
      findHeaders(headerArr, $(selectedElement));
      exactPath = $(selectedElement).getPath();
      var collapsableHeaders = headerArr;
      $('#reportTourEntryList .active').data('collapsableHeaders', collapsableHeaders);
      $('#reportTourEntryList .active').data('exactPath', exactPath);
      if($('#reportTourHoverElement').hasClass('isSvgElement')){
        $('#reportTourEntryList .active').data('isSvgElement', 'true');
      }else{
        $('#reportTourEntryList .active').data('isSvgElement', 'false');
      }
      if($('#reportTourHoverElement').hasClass('isScreenshot')){
        $('#reportTourEntryList .active').data('isScreenshot', 'true');
      }else{
        $('#reportTourEntryList .active').data('isScreenshot', 'false');
      }
      saveReportTourEntryListJson();
    }

     var findHeaders = function(headerArr, element){
       if(element.closest('.bd').length != 0){
          if(element.closest('.bd').prev().find('*[data-pos]:not(.hide-all, .signature-description)').length != 0){
            var headerPos = element.closest('.bd').prev().find('*[data-pos]:not(.hide-all, .signature-description, .generateSig)').data('pos');
            headerArr.push(headerPos);
            findHeaders(headerArr, element.closest('.bd').prev().find('*[data-pos]:not(.hide-all, .signature-description)'));
          }else{
            console.log('This is in Behavior. A Special Case, when header exist but doesnt have data-pos. Should never happen. If you see this message, please contact developer.');
          }
       }
     }

     var updateTitleAndDescription = function(title, description){
       if(description != ''){
         $('#reportTourExplanationBoxPlaceholderText').hide();
         $('#reportTourExplanationBoxDescription').show();
       }else{
         $('#reportTourExplanationBoxPlaceholderText').show();
         $('#reportTourExplanationBoxDescription').hide();
       }
       $('#reportTourExplanationBox #reportTourExplanationBoxDescription').html(description.replace(/\r\n|\r|\n/g,'<br />'));
       var reportTourExplanationBoxHeight = parseInt($('#reportTourExplanationBox').height());
       var reportTourExplanationBoxWidth = parseInt($('#reportTourExplanationBox').width());
       var reportTourExplanationBoxPaddingRight = parseInt($('#reportTourExplanationBox').css('padding-right'));
       if($('#reportTourHoverElement').hasClass('isScreenshot')){

          $('.slideshow-thumbs.selectedScreenshot').addClass('currently-selecting');
          var reportTourExplanationBoxTop = parseInt($('.slideshow-thumbs.selectedScreenshot').offset().top);
          var reportTourExplanationBoxLeft = parseInt($('.slideshow-thumbs.selectedScreenshot').offset().left);
          selectedElementWidth = $('.slideshow-thumbs.selectedScreenshot').width();
          var imgSrc = $('.slideshow-thumbs.selectedScreenshot').data('src');
          $('#deviceScreen').attr('src', imgSrc);
          $('.slideshow-thumbs.selectedScreenshot').removeClass('currently-selecting');

       }else{
        var reportTourExplanationBoxTop = parseInt($('#reportTourHoverElement').offset().top);
        var reportTourExplanationBoxLeft = parseInt($('#reportTourHoverElement').offset().left);
        selectedElementWidth = parseInt($('#reportTourHoverElement').width());
       }

       var topCalculated = parseInt(reportTourExplanationBoxTop - (reportTourExplanationBoxHeight+33));
       var leftCalculated = parseInt(reportTourExplanationBoxLeft + ((selectedElementWidth/2)-(reportTourExplanationBoxWidth/2)-12));

       $('#reportTourExplanationBox').css({
          'top' : topCalculated,
          'left' : leftCalculated
       });
       saveReportTourEntryListJson();
     }
     
    var reselectSvgElement = function(elem){
      var height = parseInt($(elem)[0].getBoundingClientRect().height);
      var width = parseInt($(elem)[0].getBoundingClientRect().width);
      var selectedElementOffset = $(elem).offset();
      var reduceWidthAndHeight = 0;

      if($('#reportTourEntryList li.active').data('svgElementType') == 'behaviorGraph'){
        $('#reportTourHoverElement').css('border-radius', '10px');
        reduceWidthAndHeight = 10;
      }else{
        $('#reportTourHoverElement').css('border-radius', '0px');
        reduceWidthAndHeight = 5;
      }

      $('#reportTourHoverElement').css({
         'top' : (selectedElementOffset.top - 2) + 'px',
         'left' : (selectedElementOffset.left - 2) + 'px'
      });
      $('#reportTourHoverElement').width(width-reduceWidthAndHeight);
      $('#reportTourHoverElement').height(height-reduceWidthAndHeight);

      $('#reportTourHoverElement').addClass('isSvgElement');
      selectedElementWidth = width;
      selectedElementHeight = height;
      selectedElement = $(elem);
    }
	  var createBoundingBoxAroundElement = function(elem, isSvgElement, isScreenshot){

      $('.slideshow-thumbs').each(function(){
        $(this).css('box-shadow', 'inset 0px 0px 0px 0px webkit-border-bottom-left-radius');
      });
      $('.selectedScreenshot').removeClass('selectedScreenshot');
      if(isScreenshot == 'true'){
        $(elem).addClass('selectedScreenshot');
        selectedElement = $(elem);
        $('#reportTourHoverElement').addClass('isScreenshot');
      }else{
  	    $('#reportTourHoverElement').show();
  	    var elemId = $(elem).attr('id');
        if(isSvgElement){
          $('#reportTourHoverElement').removeClass('isScreenshot');
          var svgType = $(elem).closest('.graphWrapper');
          if(svgType.hasClass('svgGraph') || svgType.hasClass('cfgGraph') || svgType.hasClass('callGraph')){
            var originalPos = $(elem).find('a').attr('data-pos');
            htmlResultElement = $(elem).find('a');
            var elementHref = htmlResultElement.attr('xlink:href');
            var nodeId = elementHref.substring(1);
            var wrapperElement = htmlResultElement.closest('.graphWrapper');
            if(wrapperElement.hasClass('svgGraph')){
              var targetId = wrapperElement.data('targetid');
              graphId = 'graphWrapper_'+targetId;
            }else if(wrapperElement.hasClass('cfgGraph')){
              var targetId = wrapperElement.data('functionid');
              graphId = 'cfgWrapper_'+targetId;
            }else if(wrapperElement.hasClass('callGraph')){
              var targetId = wrapperElement.data('targetid');
              graphId = 'callgraphWrapper_'+targetId;
            }
            jumpToNode(graphId, nodeId, wrapperElement, targetId);
          }

          
          var i;
          for (i = 0; i < 2; i++) { 
            setTimeout(function(){
              reselectSvgElement(elem);
              updateTitleAndDescription('title', $('#reportTourExplanationBox #reportTourExplanationBoxDescription').html());
            }, 100);
          }


        }else{
          $('#reportTourHoverElement').removeClass('isScreenshot');

          if($(elem).closest('svg').length > 0){
            if($(elem).closest('svg').find('.node').length > 0){
              $(elem).closest('svg').find('.node').each(function(){
                var height = parseInt($(this)[0].getBoundingClientRect().height);
                var width = parseInt($(this)[0].getBoundingClientRect().width);
                var selectedElementOffset = $(this).offset();
                if((selectedElementOffset.top < event.pageY && event.pageY < selectedElementOffset.top + height && selectedElementOffset.left < event.pageX && event.pageX < selectedElementOffset.left + width)){
                  $('#reportTourEntryList li.active').data('svgElementType', $(elem).closest('svg').parent().attr('id'));
                  var reduceWidthAndHeight = 0;
                  if($(elem).closest('svg').parent().attr('id') == 'behaviorGraph'){
                    $('#reportTourEntryList li.active').data('svgElementType', 'behaviorGraph');
                    $('#reportTourHoverElement').css('border-radius', '10px');
                    reduceWidthAndHeight = 10;
                  }else{
                    $('#reportTourHoverElement').css('border-radius', '0px');
                    reduceWidthAndHeight = 5;
                  }
                  $('#reportTourHoverElement').css({
                     'top' : (selectedElementOffset.top - 2) + 'px',
                     'left' : (selectedElementOffset.left - 2) + 'px'
                  });
                  $('#reportTourHoverElement').width(width-reduceWidthAndHeight);
                  $('#reportTourHoverElement').height(height-reduceWidthAndHeight);
                  $('#reportTourHoverElement').addClass('isSvgElement');
                  selectedElementWidth = width;
                  selectedElementHeight = height;
                  selectedElement = $(this);
                }
              });
            }
            return;
          }

          if($(elem).prop('tagName') != undefined){
            if($(elem).closest('#screenshotx').length != 0 && !$(elem).hasClass('joeCollapsable')){
              if($(elem).hasClass('slideshow-thumbs')){
                $(elem).addClass('selectedScreenshot');
                selectedElement = $(elem);
                $('#reportTourHoverElement').addClass('isScreenshot');
                $('#reportTourHoverElement').hide();
              }
              $('#reportTourHoverElement').removeClass('isSvgElement');
            }else{
              
              if($(elem).closest('#reportTour').length == 0 && elemId != 'reportTour' && elemId != 'main' && !$(elem).hasClass('span12') && (!$(elem).hasClass('pagination') || $(elem).hasClass('joeCollapsable')) && elemId != 'reportTourExplanationBox' && elemId != 'reportTourExplanationBoxPlaceholderText' && elemId != 'reportTourHoverElement'){
                


                var selectedElementHeight = parseInt($(elem)[0].getBoundingClientRect().height);
                var selectedElementWidth = parseInt($(elem)[0].getBoundingClientRect().width);

                height = selectedElementHeight;
                width = selectedElementWidth;


                selectedElementOffset = $(elem).offset();

                $('#reportTourHoverElement').css({
                   'top' : (selectedElementOffset.top - 2) + 'px',
                   'left' : (selectedElementOffset.left - 2) + 'px',
                   'border-radius': '0px'
                });



                $('#reportTourHoverElement').width(selectedElementWidth-8);
                $('#reportTourHoverElement').height(selectedElementHeight-7);
                selectedElement = $(elem);
                $('#reportTourHoverElement').removeClass('isSvgElement');
                $('#reportTourHoverElement').removeClass('isScreenshot');
              }
            }
          }   
        }
      }
	  }

    var publicElementTracker;

    var getNotInlineParent = function(elem){
      var newElem = $(elem).parent()[0];
      if(newElem.tagName == 'SPAN' || 
        newElem.tagName == 'P' || 
        newElem.tagName == 'STRONG' || 
        newElem.tagName == 'H2' || 
        newElem.tagName == 'H3' || 
        newElem.tagName == 'H4' || 
        newElem.tagName == 'H5' || 
        newElem.tagName == 'H6' || 
        newElem.tagName == 'A' || 
        $(newElem).hasClass('accordion-wrapper') ||
        $(newElem).hasClass('copyToClipboard') || 
        $(newElem).hasClass('overall') || 
        $(newElem).hasClass('specific')){
        getNotInlineParent(newElem);
      }else{
        publicElementTracker = newElem;
        return newElem;
      }
    }

	  var appendReportTourHoverElement = function(event){
	    var elem = document.elementFromPoint(event.pageX, event.clientY);
      publicElementTracker = elem;
      if(elem.tagName == 'SPAN' || 
        elem.tagName == 'P' || 
        elem.tagName == 'STRONG' || 
        elem.tagName == 'H2' || 
        elem.tagName == 'H3' || 
        elem.tagName == 'H4' || 
        elem.tagName == 'H5' || 
        elem.tagName == 'H6' || 
        elem.tagName == 'A' || 
        $(elem).hasClass('accordion-wrapper') || 
        $(elem).hasClass('copyToClipboard') || 
        $(elem).hasClass('overall') || 
        $(elem).hasClass('specific')){
        elem = getNotInlineParent(elem);
      }
	    createBoundingBoxAroundElement(publicElementTracker, false, false);
	  }
    
    // When resizing browser window
    var resizeTimer;
    $(window).on('resize', function() {
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(function() {
            if ($('#showReportTourPagination').is(':visible')) {
                $('#showReportTourPagination li.active').click();
            }
        }, 250);
    });

	  // Interface Logic
	  $(document).on('click', '#reportTourEntryAddStep', function(){
	    var title = 'Step '+($('#reportTourEntryList li').length+1);
	    var description = '';
	    $('#reportTourEntryList').append('\
	      <li><div class="cutTextLength">'+title+'</div><div class="deleteButton"><div class="reportTourInterfaceSprite delete"></div></div></li>\
	    ');

      var reportTourEntryList = $('#reportTourEntryList');
      reportTourEntryList.scrollTop(reportTourEntryList.prop("scrollHeight"));

	    $('#reportTourEntryList li').last().data('title', title);
	    $('#reportTourEntryList li').last().data('description', description);
	    $('#reportTourEntryList li').last().click();
	  });
	  $(document).on('click', '#reportTourEntryListUp', function(){
	    $('#reportTourEntryList li.active').prev().insertAfter($('#reportTourEntryList li.active'));
	  });
	  $(document).on('click', '#reportTourEntryListDown', function(){
	    $('#reportTourEntryList li.active').next().insertBefore($('#reportTourEntryList li.active'));
	  });
    $(document).on('click', '#reportTourEntryList li .deleteButton', function(e){
      e.stopPropagation();
      $(this).parent().addClass('willGetRemoved');
      var index = $(this).parent().parent().parent().find('ul li.willGetRemoved').index();
      if($(this).parent().hasClass('active')){
        if(index == 0){
          $(this).parent().next().click();
        }else{
          $(this).parent().prev().click();
        }
      }
      $(this).parent().remove();
    });

	  $(document).on('click', '#reportTourEntryList li', function(){
	    $('#reportTourEntryList li.active').removeClass('active');
	    var title =  $(this).data('title').trim();
	    var description = $(this).data('description');
      var isSvgElement = $(this).data('isSvgElement');
      var isScreenshot = $(this).data('isScreenshot');
      var svgElementType = $(this).data('svgElementType');


      expandHeaders($(this).data('collapsableHeaders'));
	    var selectedElement = $(this).data('selectedElement');

      if(selectedElement){
        if(selectedElement.hasClass('suspicious') || selectedElement.hasClass('clean') || selectedElement.hasClass('info')){
          if(!$('#expertMode').hasClass('active')){
            $('#expertMode').click();
          }
        }

        if(selectedElement.closest('.show-source').length > 0){
          if(!selectedElement.closest('.show-source').prev().hasClass('expanded')){
            selectedElement.closest('.show-source').prev().find('.accordion-toggle').click();
          }
        }
      }


	    if(selectedElement != undefined && selectedElement.length > 0){
        saveReportTourEntryListJson();
        if(!isScreenshot){
          $('#reportTourHoverElement').show();
        }
	      $('#reportTourExplanationBox').show();
	      $('#selectedElement').html('Element selected');
	      $('#selectedElement').attr('title', selectedElement.text());

	      createBoundingBoxAroundElement(selectedElement, isSvgElement, isScreenshot);

        var svgType = selectedElement.closest('.graphWrapper');
        if(!svgType.hasClass('svgGraph')){
          $('html, body').animate({
            scrollTop: $(selectedElement).offset().top-($(window).height()/2)
          }, 500);
        }
	    }else{
	      $('#reportTourHoverElement').hide();
	      $('#reportTourExplanationBox').hide();
	      $('#selectedElement').removeClass('selected');
	      $('#selectedElement').addClass('empty');
	      $('#selectedElement').html('Nothing selected');
	      $('#selectedElement').attr('title', 'Nothing selected');
	    }
	    $('#reportTourTitle').val(title);
	    $('#reportTourDescription').val(description);
	    $(this).addClass('active');
	    updateTitleAndDescription($('#reportTourTitle').val(), $('#reportTourDescription').val());
	  });

	  $(document).on('keyup', '#reportTourTitle', function(){
	    var changedTitle = $(this).val();
	    $('#reportTourEntryList li.active .cutTextLength').text(changedTitle);
	    $('#reportTourEntryList li.active').data('title', changedTitle);
	    updateTitleAndDescription($('#reportTourTitle').val(), $('#reportTourDescription').val());
	  });
	  $(document).on('keyup', '#reportTourDescription', function(){
	    var changedDescription = $(this).val();
	    $('#reportTourEntryList li.active').data('description', changedDescription);
	    updateTitleAndDescription($('#reportTourTitle').val(), $('#reportTourDescription').val());
	  });

	  $(document).on('click', '#selectElement', function(){
	    if($(this).hasClass('active')){
	      $(this).removeClass('active');
	      $(document).off('mousemove', appendReportTourHoverElement);
	      $(document).off('click', clickReportTourElement);
	      $('#reportTourHoverElement').hide();
	    }else{
        reportTourElementSelecting = true;
	      $(this).addClass('active');
        if(typeof selectedElement != "undefined"){
          if(!selectedElement.hasClass('selectedScreenshot')){
            $('#reportTourHoverElement').show();
          }
        }
	      $(document).on('click', clickReportTourElement);
	      $(document).on('mousemove', appendReportTourHoverElement);
	    }    
	  });
	  $(document).on('click', '#closeReportTour', function(event){
	    $('#reportTour').hide();
      $('#reportTourHoverElement').hide();
      $('#reportTourExplanationBox').hide();
      event.stopPropagation();
	  });
	  // init Report Tour Edit Interface
	  var initReportTour = function(){
	    if(!$('#reportTour').hasClass('initialized')){
	      $('#reportTour').addClass('initialized');
        var checkForFail = typeof reportTourEntryListJson == 'undefined' || reportTourEntryListJson === '[]';
	      if (completeReportTourTitle != 'Not Saved' && !checkForFail) {
	        for(i = 0; i < reportTourEntryListJson.length; i++){
	          $('#reportTourEntryList').append('<li><div class="cutTextLength">'+reportTourEntryListJson[i].title+'</div><div class="deleteButton"><div class="reportTourInterfaceSprite delete"></div></div></li>');
	          $('#reportTourEntryList li:last').data('title', reportTourEntryListJson[i].title);
	          $('#reportTourEntryList li:last').data('description', reportTourEntryListJson[i].description);
	          $('#reportTourEntryList li:last').data('selectionType', reportTourEntryListJson[i].selectionType);
	          $('#reportTourEntryList li:last').data('selection', reportTourEntryListJson[i].selection);
	          $('#reportTourEntryList li:last').data('collapsableHeaders', reportTourEntryListJson[i].collapsableHeaders);
            $('#reportTourEntryList li:last').data('exactPath', reportTourEntryListJson[i].exactPath);
            $('#reportTourEntryList li:last').data('isSvgElement', reportTourEntryListJson[i].isSvgElement);
            $('#reportTourEntryList li:last').data('isScreenshot', reportTourEntryListJson[i].isScreenshot);
            $('#reportTourEntryList li:last').data('svgElementType', reportTourEntryListJson[i].svgElementType);
            expandHeaders(reportTourEntryListJson[i].collapsableHeaders);
	          selectedElement = parseSelectedElement(reportTourEntryListJson[i].selectionType, reportTourEntryListJson[i].selection, reportTourEntryListJson[i].exactPath);
	          $('#reportTourEntryList li:last').data('selectedElement', selectedElement);
	        }
	      }else{
	        if($('#reportTourEntryList li').length == 0){
            $('#reportTourEntryAddStep').click();
	        }
	      }
	      $('#reportTourEntryList li:first').click();
	    }
	  }
	  $(document).on('click', '#showReportTourClose', function(event){
	    $('#showReportTour').hide();
      $('#reportTourHoverElement').hide();
      $('#reportTourExplanationBox').hide();
      event.stopPropagation();
	  });
	  $(document).on('click', '#showReportTourNavForward', function(){
	    if(!$(this).hasClass('disabled')){
	      $('#showReportTourPagination li.active').next().click();
	    }
	  });
	  $(document).on('click', '#showReportTourNavBack', function(){
	    if(!$(this).hasClass('disabled')){
	      $('#showReportTourPagination li.active').prev().click();
	    }
	  });
	  $(document).on('click', '#showReportTourPagination li', function(){
	    var nmbrOfElements = $('#showReportTourPagination li').length;
	    var index = $(this).text();
	    var title = $(this).data('title');
	    var description = $(this).data('description');
	    var selectionType = $(this).data('selectionType');
	    selection = $(this).data('selection');
	    var collapsableHeaders = $(this).data('collapsableHeaders');
      var exactPath = $(this).data('exactPath');
      var isSvgElement = $(this).data('isSvgElement');
      var isScreenshot = $(this).data('isScreenshot');
      var svgElementType = $(this).data('svgElementType');
	    $('#showReportTourPagination li').removeClass('active');
	    $(this).addClass('active');
      if(nmbrOfElements == 1){
        $('#showReportTourNav').hide();
      }
	    if(parseInt(index) == 1){
	      $('#showReportTourNavBack').addClass('disabled');
	      $('#showReportTourNavForward').removeClass('disabled');
	    }
	    if(parseInt(index) == nmbrOfElements){
	      $('#showReportTourNavBack').removeClass('disabled');
	      $('#showReportTourNavForward').addClass('disabled');
	    }
	    if(parseInt(index) != nmbrOfElements && parseInt(index) != 1){
	      $('#showReportTourNavBack').removeClass('disabled');
	      $('#showReportTourNavForward').removeClass('disabled');
	    }
	    $('#showReportTourEntryTitle').html(title);
	    $('#showReportTourIndex').html(index);



      if($('#completeReportTourTitleId').val() != ''){
        $('#showReportTourHeader h5').html($('#completeReportTourTitleId').val());
      }else if(completeReportTourTitle != 'Not Saved'){
        $('#showReportTourHeader h5').html(completeReportTourTitle);
      }else{
        $('#showReportTourHeader h5').html('Untitled Tour');
      }

      expandHeaders(collapsableHeaders);
      selectedElement = parseSelectedElement(selectionType, selection, exactPath);

      if(selectedElement.length != 0){

        if(selectedElement.hasClass('suspicious') || selectedElement.hasClass('clean') || selectedElement.hasClass('info')){
          if(!$('#expertMode').hasClass('active')){
            $('#expertMode').click();
          }
        }

        if(selectedElement.closest('.show-source').length > 0){
          if(!selectedElement.closest('.show-source').prev().hasClass('expanded')){
            selectedElement.closest('.show-source').prev().find('.accordion-toggle').click();
          }
        }


        $('#reportTourHoverElement').show();
        $('#reportTourExplanationBox').show();
        createBoundingBoxAroundElement(selectedElement, isSvgElement, isScreenshot);
        updateTitleAndDescription(title, description);

        var svgType = $(selectedElement).closest('.graphWrapper');
        if(!svgType.hasClass('svgGraph')){
          setTimeout(function() {
            $('html, body').animate({
              scrollTop: $(selectedElement).offset().top-($(window).height()/2)
            }, 500);
          }, 1);
        }
      }
	  });
    var expandHeaders = function(collapsableHeaders){
      if(typeof collapsableHeaders !== 'undefined'){
        for(var i = 0; i < collapsableHeaders.length; i++){
          var currentEl = (collapsableHeaders.length - i)-1;
          if($('*[data-pos="'+collapsableHeaders[currentEl]+'"]').prop("tagName") == 'A'){
            if($('*[data-pos="'+collapsableHeaders[currentEl]+'"]').closest('.accordion-wrapper').hasClass('collapsed')){
              $('*[data-pos="'+collapsableHeaders[currentEl]+'"]').click();
            }else if($('*[data-pos="'+collapsableHeaders[currentEl]+'"]').hasClass('show-all')){
              $('*[data-pos="'+collapsableHeaders[currentEl]+'"]').click();
            }
          }else{
            if($('*[data-pos="'+collapsableHeaders[currentEl]+'"]').closest('.accordion-wrapper').hasClass('collapsed')){
              $('*[data-pos="'+collapsableHeaders[currentEl]+'"]').closest('.accordion-toggle').click();
            }
          }
        }
      }
    }

	  var parseSelectedElement = function(selectionType, selection, exactPath){
	    selectedElement = undefined;
	    if(selectionType == 'data-pos'){
	      selectedElement = $('*[data-pos="'+selection+'"]');
	    }else if(selectionType == 'exact-path'){
        selectedElement = $(exactPath);
      }else if(selectionType == 'screenshot'){
        selectedElement = $('.slideshow-thumbs:nth-child('+(selection+1)+')');
      }
	    return selectedElement;
	  }
    var initReportTourInterface = function(){
      if(typeof reportTourEntryListJson == 'undefined' || reportTourEntryListJson === '[]'){
        $('#edit-interactive-tour span').html('Create Interactive Tour');
        $('#play-interactive-tour').hide();
      }else{
        $('#play-interactive-tour').show();
      }
    }
	  var initShowReportTour = function(){
      if($('#completeReportTourTitleId').val() != ''){
        completeReportTourTitle = $('#completeReportTourTitleId').val();
      }
      $('#showReportTourPagination').html('');
      if(typeof reportTourEntryListJson === 'string'){
        reportTourEntryListJson = JSON.parse(reportTourEntryListJson);
      }
  		if(typeof reportTourEntryListJson !== 'undefined'){
		    for(i = 0; i < reportTourEntryListJson.length; i++){
		      var index = i + 1;
		      $('#showReportTourPagination').append('<li>'+index+'</li>');
		      $('#showReportTourPagination li:last').data('title', reportTourEntryListJson[i].title);
		      $('#showReportTourPagination li:last').attr('title', reportTourEntryListJson[i].title);
		      $('#showReportTourPagination li:last').data('description', reportTourEntryListJson[i].description);
		      $('#showReportTourPagination li:last').data('selectionType', reportTourEntryListJson[i].selectionType);
		      $('#showReportTourPagination li:last').data('selection', reportTourEntryListJson[i].selection);
		      $('#showReportTourPagination li:last').data('collapsableHeaders', reportTourEntryListJson[i].collapsableHeaders);
          $('#showReportTourPagination li:last').data('exactPath', reportTourEntryListJson[i].exactPath);
          $('#showReportTourPagination li:last').data('isSvgElement', reportTourEntryListJson[i].isSvgElement);
          $('#showReportTourPagination li:last').data('isScreenshot', reportTourEntryListJson[i].isScreenshot);
          $('#showReportTourPagination li:last').data('svgElementType', reportTourEntryListJson[i].svgElementType);
		    }
  		}
	  }

	  $('#play-interactive-tour').click(function(){
      initShowReportTour();
      initReportTour();
	    $('#reportTour').hide();
	    $('#showReportTour').show();
	    $('#showReportTourPagination li:first').click();
	  });
	  $('#edit-interactive-tour').click(function(){
	    initReportTour();
	    $('#showReportTour').hide();
	    $('#reportTour').show();
	    $('#reportTourEntryList li:first').click();
      if($(this).find('span').text() == 'Create Interactive Tour'){
        $('#play-interactive-tour').show();
        $(this).find('span').text('Edit Interactive Tour');
      }
	  });

    $(window).bind("load", function() {
  	  setTimeout(function(){
        initReportTourInterface();
        if(typeof initReportTourOnStart !== 'undefined'){
          if(initReportTourOnStart){
            $('#play-interactive-tour').click();
          }
        }
  	  }, 1000);
    });

    $(document).on('click', function(e){

      var eventOffsetX = e.pageX;
      var eventOffsetY = e.pageY;

      var hoverElementOffset = $('#reportTourHoverElement').offset();

      clickIsInsideHorizontally = eventOffsetX >= hoverElementOffset.left && eventOffsetX <= hoverElementOffset.left + $('#reportTourHoverElement').width();

      clickIsInsideVertically = eventOffsetY >= hoverElementOffset.top && eventOffsetY <= hoverElementOffset.top + $('#reportTourHoverElement').height();

      if(clickIsInsideHorizontally && clickIsInsideVertically){
        $('html, body').stop(true, false);
        if(selectedElement.hasClass('joeCollapsable')){
          selectedElement.find('.accordion-toggle').click();
        }
      }

      if(typeof selectedElement != "undefined"){
        var selectedElementVisible = selectedElement.is(":visible");
        if(selectedElement.hasClass('selectedScreenshot')){
          return;
        }

        if(selectedElementVisible){
          $('#reportTourHoverElement').show();
          $('#reportTourExplanationBox').show();
        }else{
          $('#reportTourHoverElement').hide();
          $('#reportTourExplanationBox').hide();
        }
      }
    });
	  
	  // END OF REPORT TOUR CODE
	  // ---------------------------------------------------------
	  // ---------------------------------------------------------
	  // ---------------------------------------------------------
	  // ---------------------------------------------------------
	  // ---------------------------------------------------------


    var updateSvgBoundingBox = function(){
      var isSvgElement = $('#reportTourHoverElement').hasClass('isSvgElement');
      if(isSvgElement){
        var elem = undefined;
        if($('#showReportTour').is(":visible")){
          elem = $('#showReportTourPagination li.active').data('selectedElement');
        }else if($('#reportTour').is(":visible")){
          elem = $('#reportTourEntryList li.active').data('selectedElement');
        }
        if(elem != undefined){
          reselectSvgElement(elem);
        }
      }
      updateTitleAndDescription('title', $('#reportTourExplanationBox #reportTourExplanationBoxDescription').html());
    }
  


function downloadTour(data, name, type) {
    if (data !== null && navigator.msSaveBlob){
      return navigator.msSaveBlob(new Blob([data], { type: type }), name);
    }
    var a = $("<a style='display: none;'/>");
    var url = {};

    if(window.URL.createObjectURL){
      url = window.URL.createObjectURL(new Blob([data], {type: type}));
    }else{
      url = window.webkitURL.createObjectURL(new Blob([data], {type: type}));
    }
    
    a.attr("href", url);
    a.attr("download", name);
    $("body").append(a);
    a[0].click();
    if(window.URL.createObjectURL){
      url = window.URL.revokeObjectURL(url);
    }else{
      url = window.webkitURL.revokeObjectURL(url);
    }
    a.remove();
}


var reportTourEntryListJson;

if(typeof completeReportTourTitle == "undefined"){
  completeReportTourTitle = 'Not Saved';
}

var startOnLoad;
function saveReportTourEntryListJson(){
  reportTourEntryListJson = '';
  var reportTourEntryListArr = [];
  $('#reportTourEntryList li').each(function(){
    var entry = { };
    entry.title = $(this).data('title');
    entry.description = $(this).data('description');
    entry.selectionType = 'none';
    entry.selection = 'none';
    entry.collapsableHeaders = $(this).data('collapsableHeaders');
    entry.isSvgElement = $(this).data('isSvgElement');
    entry.isScreenshot = $(this).data('isScreenshot');
    entry.svgElementType = $(this).data('svgElementType');
    var selectedElement = $(this).data('selectedElement');
    if($(selectedElement).is('[data-pos]')){
      entry.selectionType = 'data-pos';
      entry.selection = $(selectedElement).data('pos');
      if($(selectedElement).closest('.accordion-body').length != 0){
        var bodyId = $(selectedElement).closest('.accordion-body').attr('id');
      }
    }else if(entry.isScreenshot == 'true'){
      entry.selectionType = 'screenshot';
      entry.selection = $(selectedElement).index();
      $('slideshow-thumbs:nth-child('+entry.selection+')').click();
    }else{
      entry.selectionType = 'exact-path';
      entry.selection = $(selectedElement).closest('.bd').prev().find('*[data-pos]').data('pos');
      entry.exactPath = $(selectedElement).getPath();
    }
    selection = entry.selection;
    reportTourEntryListArr.push(entry);
  });
  reportTourEntryListJson = JSON.stringify(reportTourEntryListArr);
  startOnLoad = $('#startOnLoad').is(':checked');
}

$(document).ready(function(){
  $(document).on('click', '#reportTourExportHtml', function(){
    if($('#completeReportTourTitleId').val() != ''){
      completeReportTourTitle = $('#completeReportTourTitleId').val();
    }
    saveReportTourEntryListJson();
    firstNewLine = originalDocument.indexOf("\n");
    var doctype = '<!DOCTYPE html PUBLIC "-//W3C//DTD HTML 4.01//EN" "http://www.w3.org/TR/html4/strict.dtd"><!--[if lt IE 7]> <html class="no-js lt-ie9 lt-ie8 lt-ie7" lang="en"> <![endif]--><!--[if IE 7]>    <html class="no-js lt-ie9 lt-ie8" lang="en"> <![endif]--><!--[if IE 8]>    <html class="no-js lt-ie9" lang="en"> <![endif]--><!--[if gt IE 8]>--><html class="no-js" lang="en"><!--<![endif]--><head><meta http-equiv="Content-Type" content="text/html; charset=UTF-8"><script type="text/javascript">';

    var isTourEditing = originalDocument.includes('<script>/*'+'Beginning'+'-of'+'-saved'+'-tour');

    if(isTourEditing){
      i = originalDocument.lastIndexOf('<script>/*'+'Beginning'+'-of'+'-saved'+'-tour');
    }else{
      i = originalDocument.lastIndexOf("\n");
    }
    
    originalDocument = originalDocument.substring(firstNewLine, i);
    originalDocument += '<script>/*'+'Beginning'+'-of'+'-saved'+'-tour'+'*/\n'
    originalDocument += 'var completeReportTourTitle = "'+completeReportTourTitle+'";\n'
    originalDocument += 'var reportTourEntryListJson = '+reportTourEntryListJson+';\n'
    originalDocument += 'var initReportTourOnStart = '+startOnLoad+';\n'
    originalDocument += '<';
    originalDocument += '/script></body></html>';
    originalDocument = doctype + originalDocument;
    downloadTour(originalDocument, $('#reportTourFilename').val(), 'text/html');
  });
});

jQuery.fn.extend({
    getPath: function () {
        var path, node = this;
        while (node.length) {
            var realNode = node[0], name = realNode.localName;
            if (!name) break;
            name = name.toLowerCase();

            var parent = node.parent();

            var sameTagSiblings = parent.children(name);
            if (sameTagSiblings.length > 1) { 
                allSiblings = parent.children();
                var index = allSiblings.index(realNode) + 1;
                if (index > 1) {
                    name += ':nth-child(' + index + ')';
                }
            }
            path = name + (path ? '>' + path : '');
            node = parent;
        }
        return path;
    }
});


